// contact_body, mechanism n
template <int L>
__device__ void contact_body_copy_n(const FieldWords &w, uint32_t store) {
    __shared__ uint32_t stj[CONTACT_ROWS][32], sts[CONTACT_ROWS][32], stk[CONTACT_ROWS][32];
    __shared__ uint64_t st0[CONTACT_ROWS][32], st1[CONTACT_ROWS][32], st2[CONTACT_ROWS][32];
    __shared__ uint32_t crlo[CONTACT_ROWS][32], crhi[CONTACT_ROWS][32], crlv[CONTACT_ROWS][32];
    __shared__ RowCls rcs[CONTACT_ROWS];
    const uint32_t warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const uint32_t parts = span_parts(S);
    const bool active = lane < S * parts;
    const uint32_t entry = lane % S, part = lane / S, m = entry % n;
    const uint64_t rows = (uint64_t)w.H * w.T;
    const uint64_t rows1 = (uint64_t)w.T + w.R;
    for (uint64_t hg = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; hg < rows; hg += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint32_t h = hg / w.T;
        const uint64_t g = hg % w.T;
        if (skipped_row(w, g)) {
            if (lane < n) {
                const uint32_t mc = h * n + lane;
                w.y[g * w.M2 + mc] = 0;
                w.y[g * w.M2 + w.M + mc] = 0;
            }
            continue;
        }
        const uint32_t r = w.site_region[g];
        const uint64_t first = w.region_off[r];
        const uint32_t sites = w.region_off[r + 1] - (uint32_t)first, i = w.site_pos[g];
        const uint32_t *members = w.members + (uint64_t)h * w.T + first;
        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t c = w.cls[hg];
        const uint32_t K = row_prepare(w, hg, off, rcs[warp], lane);
        const int64_t *words = w.qf + ((uint64_t)h * w.T + first) * S;
        const int64_t *values = w.vf + ((uint64_t)h * w.T + first) * S;
        const int64_t *wi = w.pq + ((uint64_t)h * w.T + g) * S;
        const uint64_t prow0 = (uint64_t)h * rows1 + first + r;
        const wide *swp = w.sw + prow0 * S;
        const wide *svp = w.sv + prow0 * S;
        const uint64_t *scp = w.sc + prow0;
        const uint32_t nslots = rcs[warp].open ? 0 : crowd_slots(sites);
        const wide temper = temper_of(w, h, rcs[warp].open != 0);
        const int64_t amin = w.amin[hg];
        uint64_t *erow = w.e + (uint64_t)h * w.E + w.region_eoff[r] + (uint64_t)i * sites;
        // The row's support entries' addresses (the clock's skins stand there).
        const uint64_t srow = support_row(w, r, i);
        Big<L> M = big_zero<L>();
        Big<L> N = big_zero<L>();
        uint32_t negs = 0, met = 0;
        // The numerators of a staged term: the lanes of an entry add their part of it.
        const bool still_h = skinless(w, h), paced_h = paced_at(w, h, g);
        const auto numerators = [&](bool crowd, uint32_t nvalid) {
            if (!active) {
                return;
            }
            if constexpr (L <= WINDOW_LIMBS) {
                if (!crowd) {
                    // The chunk's terms by limb (`stj`, `sts`, `st0`, `st1` ranked), those of one limb summed.
                    uwide ulo = 0, uhi = 0;
                    uint32_t cq = 0xFFFFFFFFu;
                    // Two terms at a time: their values, skins and products are independent, so the loads and the
                    // multiplications of both are in flight together; they are then added in rank order.
                    const auto product = [&](uint32_t pos, uwide *xlo, uwide *xhi, uint32_t *negative) {
                        const uint32_t j = stj[warp][pos];
                        const uint32_t gap = j > i ? j - i : i - j;
                        const int64_t raw = values[(uint64_t)j * S + entry];
                        // (a head of eight modes reads its skin from the vector table: the eight modes of a gap stand together)
                        const int64_t v = still_h ? raw : paced_h ? carry_d((uint64_t)pair_skin_word(w, paced_index(w, h), srow + stk[warp][pos], m), raw) : w.n == 8 ? carry_d((uint64_t)w.decay_t[((uint64_t)h * w.dreach + gap) * 8 + m], raw) : carried_s(w, h, m, gap, raw);
                        const bool neg = v < 0;
                        const uint64_t mag = neg ? (uint64_t)0 - (uint64_t)v : (uint64_t)v;
                        const uwide lo = (uwide)st0[warp][pos] * (uwide)mag;
                        const uwide mid = (uwide)st1[warp][pos] * (uwide)mag + (lo >> 64);
                        const uwide mask = neg ? ~(uwide)0 : 0;
                        *xlo = ((mid << 64) | (uwide)(uint64_t)lo) ^ mask;
                        *xhi = (uwide)(uint64_t)(mid >> 64) ^ mask;
                        *negative = neg ? 1u : 0u;
                    };
                    const auto accumulate = [&](uint32_t pos, uwide xlo, uwide xhi, uint32_t neg) {
                        const uint32_t q = sts[warp][pos];
                        if (q != cq) {
                            if (cq != 0xFFFFFFFFu) {
                                const uint64_t top = (uint64_t)(uhi >> 64);
                                add_window_at<L, 0>(N, cq, (uint64_t)ulo, (uint64_t)(ulo >> 64), (uint64_t)uhi, top, (top >> 63) != 0 ? ~(uint64_t)0 : 0);
                            }
                            cq = q;
                            ulo = 0;
                            uhi = 0;
                        }
                        const uwide t1 = ulo + xlo;
                        const uwide t2 = t1 + (uwide)neg;
                        const uint64_t carry = (t1 < xlo) | (t2 < t1);
                        ulo = t2;
                        uhi += xhi + (uwide)carry;
                    };
                    uint32_t pos = part;
                    for (; pos + parts < nvalid; pos += 2 * parts) {
                        uwide alo, ahi, blo, bhi;
                        uint32_t an, bn;
                        product(pos, &alo, &ahi, &an);
                        product(pos + parts, &blo, &bhi, &bn);
                        accumulate(pos, alo, ahi, an);
                        accumulate(pos + parts, blo, bhi, bn);
                    }
                    if (pos < nvalid) {
                        uwide alo, ahi;
                        uint32_t an;
                        product(pos, &alo, &ahi, &an);
                        accumulate(pos, alo, ahi, an);
                    }
                    if (cq != 0xFFFFFFFFu) {
                        const uint64_t top = (uint64_t)(uhi >> 64);
                        add_window_at<L, 0>(N, cq, (uint64_t)ulo, (uint64_t)(ulo >> 64), (uint64_t)uhi, top, (top >> 63) != 0 ? ~(uint64_t)0 : 0);
                    }
                    return;
                }
            }
            for (uint32_t jj = part; jj < 32; jj += parts) {
                const uint32_t j = stj[warp][jj];
                if (j == UINT32_MAX) {
                    continue;
                }
                Coef cf;
                cf.c0 = st0[warp][jj];
                cf.c1 = st1[warp][jj];
                cf.c2 = st2[warp][jj];
                Big<L> p;
                bool neg;
                if (!crowd) {
                    const wide v = carried_ij_at(w, h, m, g, srow + stk[warp][jj], j > i ? j - i : i - j, values[(uint64_t)j * S + entry]);
                    neg = v < 0;
                    p = big_mul<L, false>(cf, mag64((int64_t)v), 0);
                } else {
                    const uint32_t lo = crlo[warp][jj], hi_ = crhi[warp][jj], lv = crlv[warp][jj];
                    const wide v = crowd_carried_wide_ij(w, h, m, g, lv, lo > i, svp[(uint64_t)(hi_ + 1) * S + entry] - svp[(uint64_t)lo * S + entry]);
                    neg = v < 0;
                    const uwide mag = (uwide)(neg ? -v : v);
                    p = big_mul<L, true>(cf, (uint64_t)mag, (uint64_t)(mag >> 64));
                }
                p = big_shl(p, sts[warp][jj]);
                if (neg) {
#pragma unroll
                    for (int k = 0; k < L; k++) {
                        p.v[k] = ~p.v[k];
                    }
                    negs += 1;
                }
                big_add(N, p);
            }
        };
        for (uint32_t k0 = 0; k0 < K; k0 += 32) {
            const uint32_t k = k0 + lane;
            const uint32_t j = k < K ? support_at(members, off, rcs[warp], i, sites, k) : UINT32_MAX;
            Coef cf = {0, 0, 0};
            uint32_t s = 0;
            uint64_t face = 0;
            if (j != UINT32_MAX) {
                // The score the exposure kept (a pair's score is computed once).
                const int64_t z = (int64_t)erow[j];
                int64_t a;
                term_of(w, z, &a, &face);
                const int64_t sh = a - amin;
                if (sh >= (int64_t)(64 * L)) {
                    atomicOr(w.status, REFUSED_CARRIER);
                } else {
                    s = (uint32_t)sh;
                }
                cf = coef_of(face, (uwide)1 << WEIGHT_BITS);
                big_add(M, big_shl(big_of<L>(cf), s));
                met += 1;
            }
            uint32_t nvalid = 32;
            if constexpr (L <= WINDOW_LIMBS) {
                // The numerators add `face |v| 2^(62 + s)` by the limb `q` it stands at: the lanes rank their
                // terms by `q` (ballots), and stage the face shifted by its bits within the limb in that order.
                const uint32_t t = s + WEIGHT_BITS, b = t & 63;
                const uint32_t key = (j != UINT32_MAX && (t >> 6) < (uint32_t)L) ? (t >> 6) : 0xFFFFFFFFu;
                const uint32_t below = lane == 0 ? 0u : 0xFFFFFFFFu >> (32 - lane);
                uint32_t rank = 0;
                nvalid = 0;
#pragma unroll
                for (int c = 0; c < L; c++) {
                    const uint32_t mk = __ballot_sync(0xFFFFFFFFu, key == (uint32_t)c);
                    rank += (key > (uint32_t)c ? __popc(mk) : 0) + (key == (uint32_t)c ? __popc(mk & below) : 0);
                    nvalid += __popc(mk);
                }
                if (key != 0xFFFFFFFFu) {
                    st0[warp][rank] = face << b;
                    st1[warp][rank] = b == 0 ? 0 : face >> (64 - b);
                    sts[warp][rank] = key;
                    stj[warp][rank] = j;
                    stk[warp][rank] = k;
                }
            } else {
                st0[warp][lane] = cf.c0;
                st1[warp][lane] = cf.c1;
                st2[warp][lane] = cf.c2;
                sts[warp][lane] = s;
                stj[warp][lane] = j;
                stk[warp][lane] = k;
            }
            __syncwarp();
            numerators(false, nvalid);
            __syncwarp();
        }
        // The crowds' chunk: a crowd's value multiplier is `2^62`, its mass multiplier its count `2^62`.
        {
            Coef cf = {0, 0, 0};
            uint32_t s = 0, slot = UINT32_MAX, lo = 0, hi_ = 0, lv = 0;
            if (lane < nslots && crowd_at(i, sites, lane, &lo, &hi_, &lv)) {
                const uint64_t count = scp[hi_ + 1] - scp[lo];
                if (count != 0) {
                    slot = lane;
                    const int64_t z = crowd_score(w, h, wi, swp + (uint64_t)lo * S, swp + (uint64_t)(hi_ + 1) * S, count, lv, temper, g, lo > i);
                    int64_t a;
                    uint64_t face;
                    term_of(w, z, &a, &face);
                    const int64_t sh = a - amin;
                    if (sh >= (int64_t)(64 * L)) {
                        atomicOr(w.status, REFUSED_CARRIER);
                    } else {
                        s = (uint32_t)sh;
                    }
                    big_add(M, big_shl(big_of<L>(coef_of(face, (uwide)count << WEIGHT_BITS)), s));
                    cf = coef_of(face, (uwide)1 << WEIGHT_BITS);
                }
            }
            st0[warp][lane] = cf.c0;
            st1[warp][lane] = cf.c1;
            st2[warp][lane] = cf.c2;
            sts[warp][lane] = s;
            stj[warp][lane] = slot;
            crlo[warp][lane] = lo;
            crhi[warp][lane] = hi_;
            crlv[warp][lane] = lv;
            __syncwarp();
            numerators(true, 32);
            __syncwarp();
        }
        // The mass over the lanes; the numerators over the parts of each entry.
        for (int o = 16; o > 0; o >>= 1) {
            const Big<L> om = shfl_big(M, o);
            big_add(M, om);
        }
        for (uint32_t o = S; parts > 1 && o < 32; o <<= 1) {
            const Big<L> on = shfl_big(N, (int)o);
            big_add(N, on);
            negs += __shfl_xor_sync(0xFFFFFFFFu, negs, (int)o);
        }
        met = (uint32_t)warp_sum_u64(met);
        // The framed current's entry `entry`: the numerator over the row's mass, to the nearest numerator. A row whose
        // support holds no keyed source (§16.20) has no mass and gathers nothing: its current is zero and no share is
        // formed (the host's `SeriesRow::release`).
        const bool empty = big_bits(M) == 0;
        Big<L> Md = M;
        if (empty) {
            Md = big_zero<L>();
            Md.v[0] = 1;
        }
        const RowDiv<L> rd = rowdiv_of(Md);
        int64_t y = 0;
        if (active && part == 0 && !empty) {
            big_add_small(N, negs);
            const bool negative = (N.v[L - 1] >> 63) != 0;
            if (negative) {
                big_negate(N);
            }
            uint64_t q = 0;
            bool ok = rowdiv_nearest(N, rd, &q);
            ok = ok && (negative ? q <= ((uint64_t)1 << 63) : q < ((uint64_t)1 << 63));
            if (ok) {
                y = (int64_t)(negative ? (uint64_t)0 - q : q);
            } else {
                atomicOr(w.status, REFUSED_WORD64);
            }
        }
        const int64_t yi = __shfl_sync(0xFFFFFFFFu, y, (lane + n) % 32);
        if (lane == 0) {
            atomicAdd(w.met + h, (unsigned long long)met);
        }
        if (lane < n) {
            wide ur, ui;
            frame_of(w, g, h, lane, &ur, &ui);
            const uint32_t mc = h * n + lane;
            w.y[g * w.M2 + mc] = fit64(rel(ur * (wide)y + ui * (wide)yi, MOVE_BITS), w.status);
            w.y[g * w.M2 + w.M + mc] = fit64(rel(ur * (wide)yi - ui * (wide)y, MOVE_BITS), w.status);
        }
        __syncwarp();
        // Pass three: each term's share of the row's mass, once, a lane a term.
        if (store) {
            for (uint32_t k = lane; k < K; k += 32) {
                const uint32_t j = support_at(members, off, rcs[warp], i, sites, k);
                if (j != UINT32_MAX) {
                    int64_t a;
                    uint64_t face;
                    term_of(w, (int64_t)erow[j], &a, &face);
                    const Big<L> x = big_shl(big_of<L>(coef_of(face, (uwide)1 << WEIGHT_BITS)), (uint32_t)(a - amin) + SHARE_BITS);
                    uint64_t p = 0;
                    if (!rowdiv_nearest(x, rd, &p)) {
                        p = UINT64_MAX;
                    }
                    erow[j] = p;
                }
            }
            uint32_t lo, hi_, lv;
            if (lane < nslots) {
                uint64_t p = 0;
                if (crowd_at(i, sites, lane, &lo, &hi_, &lv)) {
                    const uint64_t count = scp[hi_ + 1] - scp[lo];
                    if (count != 0) {
                        int64_t a;
                        uint64_t face;
                        term_of(w, crowd_score(w, h, wi, swp + (uint64_t)lo * S, swp + (uint64_t)(hi_ + 1) * S, count, lv, temper, g, lo > i), &a, &face);
                        const Big<L> x = big_shl(big_of<L>(coef_of(face, (uwide)count << WEIGHT_BITS)), (uint32_t)(a - amin) + SHARE_BITS);
                        if (!rowdiv_nearest(x, rd, &p)) {
                            p = UINT64_MAX;
                        }
                    }
                }
                w.ce[hg * w.slots + lane] = p;
            }
        }
        __syncwarp();
    }
}

extern "C" __global__ void __launch_bounds__(CONTACT_ROWS * 32, CONTACT_MIN_BLOCKS) field_copy_n_contact_l5(FieldWords w, uint32_t store) { contact_body_copy_n<5>(w, store); }
extern "C" __global__ void __launch_bounds__(CONTACT_ROWS * 32, CONTACT_MIN_BLOCKS) field_copy_n_contact_l6(FieldWords w, uint32_t store) { contact_body_copy_n<6>(w, store); }

// contact_body, mechanism r
template <int L>
__device__ void contact_body_copy_r(const FieldWords &w, uint32_t store) {
    __shared__ uint32_t stj[CONTACT_ROWS][32], sts[CONTACT_ROWS][32], stk[CONTACT_ROWS][32];
    __shared__ uint64_t st0[CONTACT_ROWS][32], st1[CONTACT_ROWS][32], st2[CONTACT_ROWS][32];
    __shared__ uint32_t crlo[CONTACT_ROWS][32], crhi[CONTACT_ROWS][32], crlv[CONTACT_ROWS][32];
    __shared__ RowCls rcs[CONTACT_ROWS];
    const uint32_t warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const uint32_t parts = span_parts(S);
    const bool active = lane < S * parts;
    const uint32_t entry = lane % S, part = lane / S, m = entry % n;
    const uint64_t rows = (uint64_t)w.H * w.T;
    const uint64_t rows1 = (uint64_t)w.T + w.R;
    for (uint64_t hg = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; hg < rows; hg += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint32_t h = hg / w.T;
        const uint64_t g = hg % w.T;
        if (skipped_row(w, g)) {
            if (lane < n) {
                const uint32_t mc = h * n + lane;
                w.y[g * w.M2 + mc] = 0;
                w.y[g * w.M2 + w.M + mc] = 0;
            }
            continue;
        }
        const uint32_t r = w.site_region[g];
        const uint64_t first = w.region_off[r];
        const uint32_t sites = w.region_off[r + 1] - (uint32_t)first, i = w.site_pos[g];
        const uint32_t *members = w.members + (uint64_t)h * w.T + first;
        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t c = w.cls[hg];
        const uint32_t K = row_prepare(w, hg, off, rcs[warp], lane);
        const int64_t *words = w.qf + ((uint64_t)h * w.T + first) * S;
        const int64_t *values = w.vf + ((uint64_t)h * w.T + first) * S;
        const int64_t *wi = w.pq + ((uint64_t)h * w.T + g) * S;
        const uint64_t prow0 = (uint64_t)h * rows1 + first + r;
        const wide *swp = w.sw + prow0 * S;
        const wide *svp = w.sv + prow0 * S;
        const uint64_t *scp = w.sc + prow0;
        const uint32_t nslots = rcs[warp].open ? 0 : crowd_slots(sites);
        const wide temper = temper_of(w, h, rcs[warp].open != 0);
        const int64_t amin = w.amin[hg];
        uint64_t *erow = w.e + (uint64_t)h * w.E + w.region_eoff[r] + (uint64_t)i * sites;
        // The row's support entries' addresses (the clock's skins stand there).
        const uint64_t srow = support_row(w, r, i);
        Big<L> M = big_zero<L>();
        Big<L> N = big_zero<L>();
        uint32_t negs = 0, met = 0;
        // The numerators of a staged term: the lanes of an entry add their part of it.
        const bool still_h = skinless(w, h), paced_h = paced_at(w, h, g);
        const auto numerators = [&](bool crowd, uint32_t nvalid) {
            if (!active) {
                return;
            }
            if constexpr (L <= WINDOW_LIMBS) {
                if (!crowd) {
                    // The chunk's terms by limb (`stj`, `sts`, `st0`, `st1` ranked), those of one limb summed.
                    uwide ulo = 0, uhi = 0;
                    uint32_t cq = 0xFFFFFFFFu;
                    // Two terms at a time: their values, skins and products are independent, so the loads and the
                    // multiplications of both are in flight together; they are then added in rank order.
                    const auto product = [&](uint32_t pos, uwide *xlo, uwide *xhi, uint32_t *negative) {
                        const uint32_t j = stj[warp][pos];
                        const uint32_t gap = j > i ? j - i : i - j;
                        const int64_t raw = values[(uint64_t)i * S + entry];
                        // (a head of eight modes reads its skin from the vector table: the eight modes of a gap stand together)
                        const int64_t v = still_h ? raw : paced_h ? carry_d((uint64_t)pair_skin_word(w, paced_index(w, h), srow + stk[warp][pos], m), raw) : w.n == 8 ? carry_d((uint64_t)w.decay_t[((uint64_t)h * w.dreach + gap) * 8 + m], raw) : carried_s(w, h, m, gap, raw);
                        const bool neg = v < 0;
                        const uint64_t mag = neg ? (uint64_t)0 - (uint64_t)v : (uint64_t)v;
                        const uwide lo = (uwide)st0[warp][pos] * (uwide)mag;
                        const uwide mid = (uwide)st1[warp][pos] * (uwide)mag + (lo >> 64);
                        const uwide mask = neg ? ~(uwide)0 : 0;
                        *xlo = ((mid << 64) | (uwide)(uint64_t)lo) ^ mask;
                        *xhi = (uwide)(uint64_t)(mid >> 64) ^ mask;
                        *negative = neg ? 1u : 0u;
                    };
                    const auto accumulate = [&](uint32_t pos, uwide xlo, uwide xhi, uint32_t neg) {
                        const uint32_t q = sts[warp][pos];
                        if (q != cq) {
                            if (cq != 0xFFFFFFFFu) {
                                const uint64_t top = (uint64_t)(uhi >> 64);
                                add_window_at<L, 0>(N, cq, (uint64_t)ulo, (uint64_t)(ulo >> 64), (uint64_t)uhi, top, (top >> 63) != 0 ? ~(uint64_t)0 : 0);
                            }
                            cq = q;
                            ulo = 0;
                            uhi = 0;
                        }
                        const uwide t1 = ulo + xlo;
                        const uwide t2 = t1 + (uwide)neg;
                        const uint64_t carry = (t1 < xlo) | (t2 < t1);
                        ulo = t2;
                        uhi += xhi + (uwide)carry;
                    };
                    uint32_t pos = part;
                    for (; pos + parts < nvalid; pos += 2 * parts) {
                        uwide alo, ahi, blo, bhi;
                        uint32_t an, bn;
                        product(pos, &alo, &ahi, &an);
                        product(pos + parts, &blo, &bhi, &bn);
                        accumulate(pos, alo, ahi, an);
                        accumulate(pos + parts, blo, bhi, bn);
                    }
                    if (pos < nvalid) {
                        uwide alo, ahi;
                        uint32_t an;
                        product(pos, &alo, &ahi, &an);
                        accumulate(pos, alo, ahi, an);
                    }
                    if (cq != 0xFFFFFFFFu) {
                        const uint64_t top = (uint64_t)(uhi >> 64);
                        add_window_at<L, 0>(N, cq, (uint64_t)ulo, (uint64_t)(ulo >> 64), (uint64_t)uhi, top, (top >> 63) != 0 ? ~(uint64_t)0 : 0);
                    }
                    return;
                }
            }
            for (uint32_t jj = part; jj < 32; jj += parts) {
                const uint32_t j = stj[warp][jj];
                if (j == UINT32_MAX) {
                    continue;
                }
                Coef cf;
                cf.c0 = st0[warp][jj];
                cf.c1 = st1[warp][jj];
                cf.c2 = st2[warp][jj];
                Big<L> p;
                bool neg;
                if (!crowd) {
                    const wide v = carried_ij_at(w, h, m, g, srow + stk[warp][jj], j > i ? j - i : i - j, values[(uint64_t)i * S + entry]);
                    neg = v < 0;
                    p = big_mul<L, false>(cf, mag64((int64_t)v), 0);
                } else {
                    const uint32_t lo = crlo[warp][jj], hi_ = crhi[warp][jj], lv = crlv[warp][jj];
                    const wide v = crowd_carried_wide_ij(w, h, m, g, lv, lo > i, svp[(uint64_t)(hi_ + 1) * S + entry] - svp[(uint64_t)lo * S + entry]);
                    neg = v < 0;
                    const uwide mag = (uwide)(neg ? -v : v);
                    p = big_mul<L, true>(cf, (uint64_t)mag, (uint64_t)(mag >> 64));
                }
                p = big_shl(p, sts[warp][jj]);
                if (neg) {
#pragma unroll
                    for (int k = 0; k < L; k++) {
                        p.v[k] = ~p.v[k];
                    }
                    negs += 1;
                }
                big_add(N, p);
            }
        };
        for (uint32_t k0 = 0; k0 < K; k0 += 32) {
            const uint32_t k = k0 + lane;
            const uint32_t j = k < K ? support_at(members, off, rcs[warp], i, sites, k) : UINT32_MAX;
            Coef cf = {0, 0, 0};
            uint32_t s = 0;
            uint64_t face = 0;
            if (j != UINT32_MAX) {
                // The score the exposure kept (a pair's score is computed once).
                const int64_t z = (int64_t)erow[j];
                int64_t a;
                term_of(w, z, &a, &face);
                const int64_t sh = a - amin;
                if (sh >= (int64_t)(64 * L)) {
                    atomicOr(w.status, REFUSED_CARRIER);
                } else {
                    s = (uint32_t)sh;
                }
                cf = coef_of(face, (uwide)1 << WEIGHT_BITS);
                big_add(M, big_shl(big_of<L>(cf), s));
                met += 1;
            }
            uint32_t nvalid = 32;
            if constexpr (L <= WINDOW_LIMBS) {
                // The numerators add `face |v| 2^(62 + s)` by the limb `q` it stands at: the lanes rank their
                // terms by `q` (ballots), and stage the face shifted by its bits within the limb in that order.
                const uint32_t t = s + WEIGHT_BITS, b = t & 63;
                const uint32_t key = (j != UINT32_MAX && (t >> 6) < (uint32_t)L) ? (t >> 6) : 0xFFFFFFFFu;
                const uint32_t below = lane == 0 ? 0u : 0xFFFFFFFFu >> (32 - lane);
                uint32_t rank = 0;
                nvalid = 0;
#pragma unroll
                for (int c = 0; c < L; c++) {
                    const uint32_t mk = __ballot_sync(0xFFFFFFFFu, key == (uint32_t)c);
                    rank += (key > (uint32_t)c ? __popc(mk) : 0) + (key == (uint32_t)c ? __popc(mk & below) : 0);
                    nvalid += __popc(mk);
                }
                if (key != 0xFFFFFFFFu) {
                    st0[warp][rank] = face << b;
                    st1[warp][rank] = b == 0 ? 0 : face >> (64 - b);
                    sts[warp][rank] = key;
                    stj[warp][rank] = j;
                    stk[warp][rank] = k;
                }
            } else {
                st0[warp][lane] = cf.c0;
                st1[warp][lane] = cf.c1;
                st2[warp][lane] = cf.c2;
                sts[warp][lane] = s;
                stj[warp][lane] = j;
                stk[warp][lane] = k;
            }
            __syncwarp();
            numerators(false, nvalid);
            __syncwarp();
        }
        // The crowds' chunk: a crowd's value multiplier is `2^62`, its mass multiplier its count `2^62`.
        {
            Coef cf = {0, 0, 0};
            uint32_t s = 0, slot = UINT32_MAX, lo = 0, hi_ = 0, lv = 0;
            if (lane < nslots && crowd_at(i, sites, lane, &lo, &hi_, &lv)) {
                const uint64_t count = scp[hi_ + 1] - scp[lo];
                if (count != 0) {
                    slot = lane;
                    const int64_t z = crowd_score(w, h, wi, swp + (uint64_t)lo * S, swp + (uint64_t)(hi_ + 1) * S, count, lv, temper, g, lo > i);
                    int64_t a;
                    uint64_t face;
                    term_of(w, z, &a, &face);
                    const int64_t sh = a - amin;
                    if (sh >= (int64_t)(64 * L)) {
                        atomicOr(w.status, REFUSED_CARRIER);
                    } else {
                        s = (uint32_t)sh;
                    }
                    big_add(M, big_shl(big_of<L>(coef_of(face, (uwide)count << WEIGHT_BITS)), s));
                    cf = coef_of(face, (uwide)1 << WEIGHT_BITS);
                }
            }
            st0[warp][lane] = cf.c0;
            st1[warp][lane] = cf.c1;
            st2[warp][lane] = cf.c2;
            sts[warp][lane] = s;
            stj[warp][lane] = slot;
            crlo[warp][lane] = lo;
            crhi[warp][lane] = hi_;
            crlv[warp][lane] = lv;
            __syncwarp();
            numerators(true, 32);
            __syncwarp();
        }
        // The mass over the lanes; the numerators over the parts of each entry.
        for (int o = 16; o > 0; o >>= 1) {
            const Big<L> om = shfl_big(M, o);
            big_add(M, om);
        }
        for (uint32_t o = S; parts > 1 && o < 32; o <<= 1) {
            const Big<L> on = shfl_big(N, (int)o);
            big_add(N, on);
            negs += __shfl_xor_sync(0xFFFFFFFFu, negs, (int)o);
        }
        met = (uint32_t)warp_sum_u64(met);
        // The framed current's entry `entry`: the numerator over the row's mass, to the nearest numerator. A row whose
        // support holds no keyed source (§16.20) has no mass and gathers nothing: its current is zero and no share is
        // formed (the host's `SeriesRow::release`).
        const bool empty = big_bits(M) == 0;
        Big<L> Md = M;
        if (empty) {
            Md = big_zero<L>();
            Md.v[0] = 1;
        }
        const RowDiv<L> rd = rowdiv_of(Md);
        int64_t y = 0;
        if (active && part == 0 && !empty) {
            big_add_small(N, negs);
            const bool negative = (N.v[L - 1] >> 63) != 0;
            if (negative) {
                big_negate(N);
            }
            uint64_t q = 0;
            bool ok = rowdiv_nearest(N, rd, &q);
            ok = ok && (negative ? q <= ((uint64_t)1 << 63) : q < ((uint64_t)1 << 63));
            if (ok) {
                y = (int64_t)(negative ? (uint64_t)0 - q : q);
            } else {
                atomicOr(w.status, REFUSED_WORD64);
            }
        }
        const int64_t yi = __shfl_sync(0xFFFFFFFFu, y, (lane + n) % 32);
        if (lane == 0) {
            atomicAdd(w.met + h, (unsigned long long)met);
        }
        if (lane < n) {
            wide ur, ui;
            frame_of(w, g, h, lane, &ur, &ui);
            const uint32_t mc = h * n + lane;
            w.y[g * w.M2 + mc] = fit64(rel(ur * (wide)y + ui * (wide)yi, MOVE_BITS), w.status);
            w.y[g * w.M2 + w.M + mc] = fit64(rel(ur * (wide)yi - ui * (wide)y, MOVE_BITS), w.status);
        }
        __syncwarp();
        // Pass three: each term's share of the row's mass, once, a lane a term.
        if (store) {
            for (uint32_t k = lane; k < K; k += 32) {
                const uint32_t j = support_at(members, off, rcs[warp], i, sites, k);
                if (j != UINT32_MAX) {
                    int64_t a;
                    uint64_t face;
                    term_of(w, (int64_t)erow[j], &a, &face);
                    const Big<L> x = big_shl(big_of<L>(coef_of(face, (uwide)1 << WEIGHT_BITS)), (uint32_t)(a - amin) + SHARE_BITS);
                    uint64_t p = 0;
                    if (!rowdiv_nearest(x, rd, &p)) {
                        p = UINT64_MAX;
                    }
                    erow[j] = p;
                }
            }
            uint32_t lo, hi_, lv;
            if (lane < nslots) {
                uint64_t p = 0;
                if (crowd_at(i, sites, lane, &lo, &hi_, &lv)) {
                    const uint64_t count = scp[hi_ + 1] - scp[lo];
                    if (count != 0) {
                        int64_t a;
                        uint64_t face;
                        term_of(w, crowd_score(w, h, wi, swp + (uint64_t)lo * S, swp + (uint64_t)(hi_ + 1) * S, count, lv, temper, g, lo > i), &a, &face);
                        const Big<L> x = big_shl(big_of<L>(coef_of(face, (uwide)count << WEIGHT_BITS)), (uint32_t)(a - amin) + SHARE_BITS);
                        if (!rowdiv_nearest(x, rd, &p)) {
                            p = UINT64_MAX;
                        }
                    }
                }
                w.ce[hg * w.slots + lane] = p;
            }
        }
        __syncwarp();
    }
}

extern "C" __global__ void __launch_bounds__(CONTACT_ROWS * 32, CONTACT_MIN_BLOCKS) field_copy_r_contact_l5(FieldWords w, uint32_t store) { contact_body_copy_r<5>(w, store); }
extern "C" __global__ void __launch_bounds__(CONTACT_ROWS * 32, CONTACT_MIN_BLOCKS) field_copy_r_contact_l6(FieldWords w, uint32_t store) { contact_body_copy_r<6>(w, store); }

// contact_body, mechanism w
template <int L>
__device__ void contact_body_copy_w(const FieldWords &w, uint32_t store) {
    __shared__ uint32_t stj[CONTACT_ROWS][32], sts[CONTACT_ROWS][32], stk[CONTACT_ROWS][32];
    __shared__ uint64_t st0[CONTACT_ROWS][32], st1[CONTACT_ROWS][32], st2[CONTACT_ROWS][32];
    __shared__ uint32_t crlo[CONTACT_ROWS][32], crhi[CONTACT_ROWS][32], crlv[CONTACT_ROWS][32];
    __shared__ RowCls rcs[CONTACT_ROWS];
    const uint32_t warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const uint32_t parts = span_parts(S);
    const bool active = lane < S * parts;
    const uint32_t entry = lane % S, part = lane / S, m = entry % n;
    const uint64_t rows = (uint64_t)w.H * w.T;
    const uint64_t rows1 = (uint64_t)w.T + w.R;
    for (uint64_t hg = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; hg < rows; hg += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint32_t h = hg / w.T;
        const uint64_t g = hg % w.T;
        if (skipped_row(w, g)) {
            if (lane < n) {
                const uint32_t mc = h * n + lane;
                w.y[g * w.M2 + mc] = 0;
                w.y[g * w.M2 + w.M + mc] = 0;
            }
            continue;
        }
        const uint32_t r = w.site_region[g];
        const uint64_t first = w.region_off[r];
        const uint32_t sites = w.region_off[r + 1] - (uint32_t)first, i = w.site_pos[g];
        const uint32_t *members = w.members + (uint64_t)h * w.T + first;
        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t c = w.cls[hg];
        const uint32_t K = row_prepare(w, hg, off, rcs[warp], lane);
        const int64_t *words = w.qf + ((uint64_t)h * w.T + first) * S;
        const int64_t *values = w.vf + ((uint64_t)h * w.T + first) * S;
        const int64_t *wi = w.pq + ((uint64_t)h * w.T + g) * S;
        const uint64_t prow0 = (uint64_t)h * rows1 + first + r;
        const wide *swp = w.sw + prow0 * S;
        const wide *svp = w.sv + prow0 * S;
        const uint64_t *scp = w.sc + prow0;
        const uint32_t nslots = rcs[warp].open ? 0 : crowd_slots(sites);
        const wide temper = temper_of(w, h, rcs[warp].open != 0);
        const int64_t amin = w.amin[hg];
        uint64_t *erow = w.e + (uint64_t)h * w.E + w.region_eoff[r] + (uint64_t)i * sites;
        // The row's support entries' addresses (the clock's skins stand there).
        const uint64_t srow = support_row(w, r, i);
        Big<L> M = big_zero<L>();
        Big<L> N = big_zero<L>();
        uint32_t negs = 0, met = 0;
        // The numerators of a staged term: the lanes of an entry add their part of it.
        const bool still_h = skinless(w, h), paced_h = paced_at(w, h, g);
        const auto numerators = [&](bool crowd, uint32_t nvalid) {
            if (!active) {
                return;
            }
            if constexpr (L <= WINDOW_LIMBS) {
                if (!crowd) {
                    // The chunk's terms by limb (`stj`, `sts`, `st0`, `st1` ranked), those of one limb summed.
                    uwide ulo = 0, uhi = 0;
                    uint32_t cq = 0xFFFFFFFFu;
                    // Two terms at a time: their values, skins and products are independent, so the loads and the
                    // multiplications of both are in flight together; they are then added in rank order.
                    const auto product = [&](uint32_t pos, uwide *xlo, uwide *xhi, uint32_t *negative) {
                        const uint32_t j = stj[warp][pos];
                        const uint32_t gap = j > i ? j - i : i - j;
                        const int64_t raw = values[(uint64_t)j * S + entry];
                        // (a head of eight modes reads its skin from the vector table: the eight modes of a gap stand together)
                        const int64_t v = still_h ? raw : paced_h ? carry_d((uint64_t)pair_skin_word(w, paced_index(w, h), srow + stk[warp][pos], m), raw) : w.n == 8 ? carry_d((uint64_t)w.decay_t[((uint64_t)h * w.dreach + gap) * 8 + m], raw) : carried_s(w, h, m, gap, raw);
                        const bool neg = v < 0;
                        const uint64_t mag = neg ? (uint64_t)0 - (uint64_t)v : (uint64_t)v;
                        const uwide lo = (uwide)st0[warp][pos] * (uwide)mag;
                        const uwide mid = (uwide)st1[warp][pos] * (uwide)mag + (lo >> 64);
                        const uwide mask = neg ? ~(uwide)0 : 0;
                        *xlo = ((mid << 64) | (uwide)(uint64_t)lo) ^ mask;
                        *xhi = (uwide)(uint64_t)(mid >> 64) ^ mask;
                        *negative = neg ? 1u : 0u;
                    };
                    const auto accumulate = [&](uint32_t pos, uwide xlo, uwide xhi, uint32_t neg) {
                        const uint32_t q = sts[warp][pos];
                        if (q != cq) {
                            if (cq != 0xFFFFFFFFu) {
                                const uint64_t top = (uint64_t)(uhi >> 64);
                                add_window_at<L, 0>(N, cq, (uint64_t)ulo, (uint64_t)(ulo >> 64), (uint64_t)uhi, top, (top >> 63) != 0 ? ~(uint64_t)0 : 0);
                            }
                            cq = q;
                            ulo = 0;
                            uhi = 0;
                        }
                        const uwide t1 = ulo + xlo;
                        const uwide t2 = t1 + (uwide)neg;
                        const uint64_t carry = (t1 < xlo) | (t2 < t1);
                        ulo = t2;
                        uhi += xhi + (uwide)carry;
                    };
                    uint32_t pos = part;
                    for (; pos + parts < nvalid; pos += 2 * parts) {
                        uwide alo, ahi, blo, bhi;
                        uint32_t an, bn;
                        product(pos, &alo, &ahi, &an);
                        product(pos + parts, &blo, &bhi, &bn);
                        accumulate(pos, alo, ahi, an);
                        accumulate(pos + parts, blo, bhi, bn);
                    }
                    if (pos < nvalid) {
                        uwide alo, ahi;
                        uint32_t an;
                        product(pos, &alo, &ahi, &an);
                        accumulate(pos, alo, ahi, an);
                    }
                    if (cq != 0xFFFFFFFFu) {
                        const uint64_t top = (uint64_t)(uhi >> 64);
                        add_window_at<L, 0>(N, cq, (uint64_t)ulo, (uint64_t)(ulo >> 64), (uint64_t)uhi, top, (top >> 63) != 0 ? ~(uint64_t)0 : 0);
                    }
                    return;
                }
            }
            for (uint32_t jj = part; jj < 32; jj += parts) {
                const uint32_t j = stj[warp][jj];
                if (j == UINT32_MAX) {
                    continue;
                }
                Coef cf;
                cf.c0 = st0[warp][jj];
                cf.c1 = st1[warp][jj];
                cf.c2 = st2[warp][jj];
                Big<L> p;
                bool neg;
                if (!crowd) {
                    const wide v = carried_ij_at(w, h, m, g, srow + stk[warp][jj], j > i ? j - i : i - j, values[(uint64_t)j * S + entry]);
                    neg = v < 0;
                    p = big_mul<L, false>(cf, mag64((int64_t)v), 0);
                } else {
                    const uint32_t lo = crlo[warp][jj], hi_ = crhi[warp][jj], lv = crlv[warp][jj];
                    const wide v = crowd_carried_wide_ij(w, h, m, g, lv, lo > i, svp[(uint64_t)(hi_ + 1) * S + entry] - svp[(uint64_t)lo * S + entry]);
                    neg = v < 0;
                    const uwide mag = (uwide)(neg ? -v : v);
                    p = big_mul<L, true>(cf, (uint64_t)mag, (uint64_t)(mag >> 64));
                }
                p = big_shl(p, sts[warp][jj]);
                if (neg) {
#pragma unroll
                    for (int k = 0; k < L; k++) {
                        p.v[k] = ~p.v[k];
                    }
                    negs += 1;
                }
                big_add(N, p);
            }
        };
        for (uint32_t k0 = 0; k0 < K; k0 += 32) {
            const uint32_t k = k0 + lane;
            const uint32_t j = k < K ? support_at(members, off, rcs[warp], i, sites, k) : UINT32_MAX;
            Coef cf = {0, 0, 0};
            uint32_t s = 0;
            uint64_t face = 0;
            if (j != UINT32_MAX) {
                // The score the exposure kept (a pair's score is computed once).
                const int64_t z = (int64_t)erow[k % sites];
                int64_t a;
                term_of(w, z, &a, &face);
                const int64_t sh = a - amin;
                if (sh >= (int64_t)(64 * L)) {
                    atomicOr(w.status, REFUSED_CARRIER);
                } else {
                    s = (uint32_t)sh;
                }
                cf = coef_of(face, (uwide)1 << WEIGHT_BITS);
                big_add(M, big_shl(big_of<L>(cf), s));
                met += 1;
            }
            uint32_t nvalid = 32;
            if constexpr (L <= WINDOW_LIMBS) {
                // The numerators add `face |v| 2^(62 + s)` by the limb `q` it stands at: the lanes rank their
                // terms by `q` (ballots), and stage the face shifted by its bits within the limb in that order.
                const uint32_t t = s + WEIGHT_BITS, b = t & 63;
                const uint32_t key = (j != UINT32_MAX && (t >> 6) < (uint32_t)L) ? (t >> 6) : 0xFFFFFFFFu;
                const uint32_t below = lane == 0 ? 0u : 0xFFFFFFFFu >> (32 - lane);
                uint32_t rank = 0;
                nvalid = 0;
#pragma unroll
                for (int c = 0; c < L; c++) {
                    const uint32_t mk = __ballot_sync(0xFFFFFFFFu, key == (uint32_t)c);
                    rank += (key > (uint32_t)c ? __popc(mk) : 0) + (key == (uint32_t)c ? __popc(mk & below) : 0);
                    nvalid += __popc(mk);
                }
                if (key != 0xFFFFFFFFu) {
                    st0[warp][rank] = face << b;
                    st1[warp][rank] = b == 0 ? 0 : face >> (64 - b);
                    sts[warp][rank] = key;
                    stj[warp][rank] = j;
                    stk[warp][rank] = k;
                }
            } else {
                st0[warp][lane] = cf.c0;
                st1[warp][lane] = cf.c1;
                st2[warp][lane] = cf.c2;
                sts[warp][lane] = s;
                stj[warp][lane] = j;
                stk[warp][lane] = k;
            }
            __syncwarp();
            numerators(false, nvalid);
            __syncwarp();
        }
        // The crowds' chunk: a crowd's value multiplier is `2^62`, its mass multiplier its count `2^62`.
        {
            Coef cf = {0, 0, 0};
            uint32_t s = 0, slot = UINT32_MAX, lo = 0, hi_ = 0, lv = 0;
            if (lane < nslots && crowd_at(i, sites, lane, &lo, &hi_, &lv)) {
                const uint64_t count = scp[hi_ + 1] - scp[lo];
                if (count != 0) {
                    slot = lane;
                    const int64_t z = crowd_score(w, h, wi, swp + (uint64_t)lo * S, swp + (uint64_t)(hi_ + 1) * S, count, lv, temper, g, lo > i);
                    int64_t a;
                    uint64_t face;
                    term_of(w, z, &a, &face);
                    const int64_t sh = a - amin;
                    if (sh >= (int64_t)(64 * L)) {
                        atomicOr(w.status, REFUSED_CARRIER);
                    } else {
                        s = (uint32_t)sh;
                    }
                    big_add(M, big_shl(big_of<L>(coef_of(face, (uwide)count << WEIGHT_BITS)), s));
                    cf = coef_of(face, (uwide)1 << WEIGHT_BITS);
                }
            }
            st0[warp][lane] = cf.c0;
            st1[warp][lane] = cf.c1;
            st2[warp][lane] = cf.c2;
            sts[warp][lane] = s;
            stj[warp][lane] = slot;
            crlo[warp][lane] = lo;
            crhi[warp][lane] = hi_;
            crlv[warp][lane] = lv;
            __syncwarp();
            numerators(true, 32);
            __syncwarp();
        }
        // The mass over the lanes; the numerators over the parts of each entry.
        for (int o = 16; o > 0; o >>= 1) {
            const Big<L> om = shfl_big(M, o);
            big_add(M, om);
        }
        for (uint32_t o = S; parts > 1 && o < 32; o <<= 1) {
            const Big<L> on = shfl_big(N, (int)o);
            big_add(N, on);
            negs += __shfl_xor_sync(0xFFFFFFFFu, negs, (int)o);
        }
        met = (uint32_t)warp_sum_u64(met);
        // The framed current's entry `entry`: the numerator over the row's mass, to the nearest numerator. A row whose
        // support holds no keyed source (§16.20) has no mass and gathers nothing: its current is zero and no share is
        // formed (the host's `SeriesRow::release`).
        const bool empty = big_bits(M) == 0;
        Big<L> Md = M;
        if (empty) {
            Md = big_zero<L>();
            Md.v[0] = 1;
        }
        const RowDiv<L> rd = rowdiv_of(Md);
        int64_t y = 0;
        if (active && part == 0 && !empty) {
            big_add_small(N, negs);
            const bool negative = (N.v[L - 1] >> 63) != 0;
            if (negative) {
                big_negate(N);
            }
            uint64_t q = 0;
            bool ok = rowdiv_nearest(N, rd, &q);
            ok = ok && (negative ? q <= ((uint64_t)1 << 63) : q < ((uint64_t)1 << 63));
            if (ok) {
                y = (int64_t)(negative ? (uint64_t)0 - q : q);
            } else {
                atomicOr(w.status, REFUSED_WORD64);
            }
        }
        const int64_t yi = __shfl_sync(0xFFFFFFFFu, y, (lane + n) % 32);
        if (lane == 0) {
            atomicAdd(w.met + h, (unsigned long long)met);
        }
        if (lane < n) {
            wide ur, ui;
            frame_of(w, g, h, lane, &ur, &ui);
            const uint32_t mc = h * n + lane;
            w.y[g * w.M2 + mc] = fit64(rel(ur * (wide)y + ui * (wide)yi, MOVE_BITS), w.status);
            w.y[g * w.M2 + w.M + mc] = fit64(rel(ur * (wide)yi - ui * (wide)y, MOVE_BITS), w.status);
        }
        __syncwarp();
        // Pass three: each term's share of the row's mass, once, a lane a term.
        if (store) {
            for (uint32_t k = lane; k < K; k += 32) {
                const uint32_t j = support_at(members, off, rcs[warp], i, sites, k);
                if (j != UINT32_MAX) {
                    int64_t a;
                    uint64_t face;
                    term_of(w, (int64_t)erow[k % sites], &a, &face);
                    const Big<L> x = big_shl(big_of<L>(coef_of(face, (uwide)1 << WEIGHT_BITS)), (uint32_t)(a - amin) + SHARE_BITS);
                    uint64_t p = 0;
                    if (!rowdiv_nearest(x, rd, &p)) {
                        p = UINT64_MAX;
                    }
                    erow[k % sites] = p;
                }
            }
            uint32_t lo, hi_, lv;
            if (lane < nslots) {
                uint64_t p = 0;
                if (crowd_at(i, sites, lane, &lo, &hi_, &lv)) {
                    const uint64_t count = scp[hi_ + 1] - scp[lo];
                    if (count != 0) {
                        int64_t a;
                        uint64_t face;
                        term_of(w, crowd_score(w, h, wi, swp + (uint64_t)lo * S, swp + (uint64_t)(hi_ + 1) * S, count, lv, temper, g, lo > i), &a, &face);
                        const Big<L> x = big_shl(big_of<L>(coef_of(face, (uwide)count << WEIGHT_BITS)), (uint32_t)(a - amin) + SHARE_BITS);
                        if (!rowdiv_nearest(x, rd, &p)) {
                            p = UINT64_MAX;
                        }
                    }
                }
                w.ce[hg * w.slots + lane] = p;
            }
        }
        __syncwarp();
    }
}

extern "C" __global__ void __launch_bounds__(CONTACT_ROWS * 32, CONTACT_MIN_BLOCKS) field_copy_w_contact_l5(FieldWords w, uint32_t store) { contact_body_copy_w<5>(w, store); }
extern "C" __global__ void __launch_bounds__(CONTACT_ROWS * 32, CONTACT_MIN_BLOCKS) field_copy_w_contact_l6(FieldWords w, uint32_t store) { contact_body_copy_w<6>(w, store); }

// field_contact_rows, mechanism n
extern "C" __global__ void __launch_bounds__(REV_ROWS * 32, 4) field_copy_n_contact_rows(FieldWords w, uint32_t h, const int64_t *dyh, int64_t *ds, int64_t *dq) {
    __shared__ uint32_t stj[REV_ROWS][32], stk[REV_ROWS][32];
    __shared__ int64_t dss[REV_ROWS][32];
    __shared__ wide dpcs[REV_ROWS][MAX_CROWD_SLOTS];
    __shared__ int64_t dsks[REV_ROWS][MAX_CROWD_SLOTS];
    __shared__ uint64_t cnts[REV_ROWS][32];
    __shared__ uint32_t crlo[REV_ROWS][32], crhi[REV_ROWS][32], crlv[REV_ROWS][32];
    __shared__ Divisor cdiv[REV_ROWS][32], cdiv2[REV_ROWS][32];
    __shared__ RowCls rcs[REV_ROWS];
    const uint32_t warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const uint32_t parts = span_parts(S);
    const bool active = lane < S * parts;
    const uint32_t entry = lane % S, part = lane / S, m = entry % n;
    const wide ln2 = (wide)(((uwide)w.ln2_hi << 64) | (uwide)w.ln2_lo);
    const bool still = skinless(w, h);
    const uint32_t g0 = still ? 0 : MOVE_BITS;
    const uint64_t rows1 = (uint64_t)w.T + w.R;
    for (uint64_t g = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; g < w.T; g += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint64_t hg = (uint64_t)h * w.T + g;
        if (skipped_row(w, g)) {
            if (lane < S) {
                const uint32_t mc = h * n + lane % n;
                const uint64_t slot = g * w.M2 + (lane < n ? mc : w.M + mc);
                w.dp[slot] = 0;
                dq[slot] = 0;
            }
            continue;
        }
        const uint32_t r = w.site_region[g];
        const uint32_t i = w.site_pos[g];
        const uint64_t first = w.region_off[r];
        const uint32_t sites = w.region_off[r + 1] - (uint32_t)first;
        const uint32_t *members = w.members + (uint64_t)h * w.T + first;
        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t c = w.cls[hg];
        const uint32_t K = row_prepare(w, hg, off, rcs[warp], lane);
        const uint64_t *e = w.e + (uint64_t)h * w.E + w.region_eoff[r] + (uint64_t)i * sites;
        int64_t *dsr = ds + w.region_eoff[r] + (uint64_t)i * sites;
        wide *dpr = w.dpb + w.region_eoff[r] + (uint64_t)i * sites;
        // The row's support entries' addresses (the clock's skins stand there).
        const uint64_t srow = support_row(w, r, i);
        const int64_t *dyi = dyh + hg * S;
        const int64_t *values = w.vf + ((uint64_t)h * w.T + first) * S;
        const int64_t *words = w.qf + ((uint64_t)h * w.T + first) * S;
        const uint64_t prow0 = (uint64_t)h * rows1 + first + r;
        const wide *swp = w.sw + prow0 * S;
        const wide *svp = w.sv + prow0 * S;
        const uint64_t *scp = w.sc + prow0;
        const uint32_t nslots = rcs[warp].open ? 0 : crowd_slots(sites);
        const wide temper = temper_of(w, h, rcs[warp].open != 0);
        const int64_t *sbr = w.sb + (uint64_t)h * w.E + w.region_eoff[r] + (uint64_t)i * sites;
        // The pair's covector `⟨δỹ_i, D ṽ_j⟩` on `2^(−40)`.
        const auto pair_dp = [&](uint32_t j, uint32_t k, uint32_t gap) -> wide {
            const int64_t *vj = values + (uint64_t)j * S;
            wide dp = 0;
            for (uint32_t x = 0; x < S; x++) {
                // [P54 step 4] The carried value is under `2^63` (`D ≤ 2^30`): the covector's product is 64 by 64.
                dp += mul64_128(dyi[x], (int64_t)carried_ij_at(w, h, x % n, g, srow + k, gap, vj[x]));
            }
            return dp;
        };
        // The same for a head of eight modes, from vector rows: the source's sixteen values as eight 16-octet loads
        // and its skins as two (`pair_score8`).
        const bool eight = w.n == 8;
        const bool still_h = skinless(w, h), paced_h = paced_at(w, h, g);
        const auto pair_dp8 = [&](uint32_t j, uint32_t k, uint32_t gap) -> wide {
            const longlong2 *v2 = reinterpret_cast<const longlong2 *>(values + (uint64_t)j * S);
            uint32_t dec[8];
            if (still_h) {
#pragma unroll
                for (int l = 0; l < 8; l++) {
                    dec[l] = 1;
                }
            } else if (paced_h) {
                pair_skins8(w, paced_index(w, h), srow + k, dec);
            } else {
                const uint4 *d4 = reinterpret_cast<const uint4 *>(w.decay_t + ((uint64_t)h * w.dreach + gap) * 8);
                const uint4 d0 = d4[0], d1 = d4[1];
                dec[0] = d0.x; dec[1] = d0.y; dec[2] = d0.z; dec[3] = d0.w;
                dec[4] = d1.x; dec[5] = d1.y; dec[6] = d1.z; dec[7] = d1.w;
            }
            wide dp = 0;
#pragma unroll
            for (int q = 0; q < 8; q++) {
                const longlong2 t = v2[q];
                dp += mul64_128(dyi[2 * q], still_h ? t.x : carry_d(dec[(2 * q) & 7], t.x));
                dp += mul64_128(dyi[2 * q + 1], still_h ? t.y : carry_d(dec[(2 * q + 1) & 7], t.y));
            }
            return dp;
        };
        // The crowds: counts, places and their divisors.
        {
            uint64_t count = 0;
            uint32_t lo = 0, hi_ = 0, lv = 0;
            if (lane < nslots && crowd_at(i, sites, lane, &lo, &hi_, &lv)) {
                count = scp[hi_ + 1] - scp[lo];
            }
            cnts[warp][lane] = count;
            crlo[warp][lane] = lo;
            crhi[warp][lane] = hi_;
            crlv[warp][lane] = lv;
            if (count != 0) {
                cdiv[warp][lane] = divisor_of(count);
                cdiv2[warp][lane] = divisor_of(count * count);
            }
        }
        __syncwarp();
        // Pass A: the weighted sum of the pairs' and crowds' covectors.
        wide weighted = 0;
        for (uint32_t k = lane; k < K; k += 32) {
            const uint32_t j = support_at(members, off, rcs[warp], i, sites, k);
            if (j == UINT32_MAX) {
                continue;
            }
            const wide p = (wide)e[j];
            const uint32_t gap = j > i ? j - i : i - j;
            const wide dpj = eight ? pair_dp8(j, k, gap) : pair_dp(j, k, gap);
            dpr[j] = dpj;
            weighted += p * dpj;
        }
        if (cnts[warp][lane] != 0) {
            const uint32_t lo = crlo[warp][lane], hi_ = crhi[warp][lane], lv = crlv[warp][lane];
            wide sum = 0;
            for (uint32_t x = 0; x < S; x++) {
                sum += (wide)dyi[x] * crowd_carried_wide_ij(w, h, x % n, g, lv, lo > i, svp[(uint64_t)(hi_ + 1) * S + x] - svp[(uint64_t)lo * S + x]);
            }
            const wide dpc = div_nearest_by(sum, cdiv[warp][lane]);
            dpcs[warp][lane] = dpc;
            weighted += (wide)w.ce[hg * w.slots + lane] * dpc;
        }
        const wide mean = rel(warp_sum(weighted), SHARE_BITS);
        // The comparison of a term `p` (its covector `dpk`): the face's.
        const auto compare = [&](wide p, wide dpk) -> wide { return rel(ln2 * rel(p * (dpk - mean), SHARE_BITS), MOVE_BITS); };
        // Pass B: δs over the pairs, in chunks of 32 into the warp's shared chunk, whose sum over the word is
        // read with the lanes over the span's entries (the probe role: `δs D ŵ_j`).
        wide sum = 0;
        // The temperature's covector (§15.10): `δT[h][kind] += release(δz S, 16)` over the row's sources and crowds,
        // each released alone and summed (an exact integer sum, the lanes' partials added over the warp).
        wide tacc = 0;
        // The covector's magnitude near and far (§16.20), where read.
        wide near_ds = 0, far_ds = 0;
        for (uint32_t k0 = 0; k0 < K; k0 += 32) {
            const uint32_t k = k0 + lane;
            const uint32_t j = k < K ? support_at(members, off, rcs[warp], i, sites, k) : UINT32_MAX;
            int64_t dsv = 0;
            if (j != UINT32_MAX) {
                const wide dzj = compare((wide)e[j], dpr[j]);
                tacc += rel(dzj * (wide)sbr[j], FACE_BITS);
                const wide dz = rel(temper * dzj, MATERIAL_BITS);
                if ((dz < 0 ? -dz : dz) >> min(w.dsbits, 63u) != 0) {
                    atomicOr(w.status, REFUSED_CARRIER);
                }
                dsv = (int64_t)dz;
                dsr[j] = dsv;
                const wide mag = dz < 0 ? -dz : dz;
                if ((j > i ? j - i : i - j) < NEAR) {
                    near_ds += mag;
                } else {
                    far_ds += mag;
                }
            }
            dss[warp][lane] = dsv;
            stj[warp][lane] = j;
            stk[warp][lane] = k;
            __syncwarp();
            if (active) {
                for (uint32_t jj = part; jj < 32; jj += parts) {
                    const uint32_t jx = stj[warp][jj];
                    if (jx != UINT32_MAX) {
                        // [P54 step 4] `δs (D ŵ_j)`: the skin and the unit word on 32 bits (their product under `2^61`), then 64 by 64.
                        sum += mul64_128(dss[warp][jj], mul32((int64_t)skin_raw_at(w, h, m, g, srow + stk[warp][jj], jx > i ? jx - i : i - jx), words[(uint64_t)jx * S + entry]));
                    }
                }
            }
            __syncwarp();
        }
        // The crowds' δs, then their share of the row's return and of the values' and the word's member
        // returns through the difference arrays.
        if (cnts[warp][lane] != 0) {
            const wide dzc = compare((wide)w.ce[hg * w.slots + lane], dpcs[warp][lane]);
            const uint32_t clo = crlo[warp][lane], chi = crhi[warp][lane], clv = crlv[warp][lane];
            const int64_t cs = crowd_base_narrow(w, h, w.pq + ((uint64_t)h * w.T + g) * S, swp + (uint64_t)clo * S, swp + (uint64_t)(chi + 1) * S, cnts[warp][lane], clv, g, clo > i);
            tacc += rel(dzc * (wide)cs, FACE_BITS);
            const wide dz = rel(temper * dzc, MATERIAL_BITS);
            if ((dz < 0 ? -dz : dz) >> min(w.dsbits, 63u) != 0) {
                atomicOr(w.status, REFUSED_CARRIER);
            }
            dsks[warp][lane] = (int64_t)dz;
            if (w.cds != nullptr) {
                w.cds[hg * w.slots + lane] = (int64_t)dz;
            }
            far_ds += dz < 0 ? -dz : dz;
        }
        if (w.dsshare != nullptr) {
            near_ds = warp_sum(near_ds);
            far_ds = warp_sum(far_ds);
            if (lane == 0) {
                add_wide(w.dsshare + 2 * h, near_ds);
                add_wide(w.dsshare + 2 * h + 1, far_ds);
            }
        }
        tacc = warp_sum(tacc);
        if (lane == 0 && tacc != 0) {
            // Into the temperature's own chart (§16.12): `δℓ = release(δT · release(T ln 2, 30), 24)`, the row's.
            add_wide(w.gcov + w.temper_at + 2 * h + (rcs[warp].open ? 1 : 0), temper_chain(w, temper, tacc));
        }
        __syncwarp();
        if (active) {
            for (uint32_t jj = part; jj < nslots; jj += parts) {
                const uint64_t count = cnts[warp][jj];
                if (count == 0) {
                    continue;
                }
                const uint32_t lo = crlo[warp][jj], hi_ = crhi[warp][jj], lv = crlv[warp][jj];
                const wide d = crowd_skin_raw(w, h, m, g, lv, lo > i);
                const wide dsk = dsks[warp][jj];
                const wide wsum = swp[(uint64_t)(hi_ + 1) * S + entry] - swp[(uint64_t)lo * S + entry];
                // [P54 step 4] Where the crowd's summed word is under `2^31`: `D W`, `D ŵ_i` and `D²` on 32 bits (under `2^61`), their
                // products by the covector, the count and `W` as 64 by 64; otherwise the wide forms.
                int32_t w32;
                wide bracket;
                if (narrow31(wsum, &w32)) {
                    sum += div_nearest_by(mul64_128(dsks[warp][jj], mul32((int64_t)d, w32)), cdiv[warp][jj]);
                    // The key's bracket released by the skin's bits once, its product by the covector checked.
                    bracket = rel((mul64_128(mul32((int64_t)d, w.pq[((uint64_t)h * w.T + g) * S + entry]), (int64_t)count) << g0) - mul64_128(mul32((int64_t)d, (int64_t)d), w32), g0);
                } else {
                    RULER_LONG();
                    sum += div_nearest_by(dsk * d * wsum, cdiv[warp][jj]);
                    bracket = rel(((d * (wide)w.pq[((uint64_t)h * w.T + g) * S + entry] * (wide)count) << g0) - d * d * wsum, g0);
                }
                wide prod = 0;
                if (!mul_fits(dsk, bracket, &prod)) {
                    atomicOr(w.status, REFUSED_KEY);
                }
                const wide pw = div_nearest_by(prod, cdiv2[warp][jj]);
                add_wide(w.cw + (first + r + lo) * S + entry, pw);
                add_wide(w.cw + (first + r + hi_ + 1) * S + entry, -pw);
                // [P54 step 4] The carried covector `release(D δỹ, 30)` on 64 bits (`carry_d`, under `2^63`), its share's product unsigned by signed.
                const int64_t cy = still ? dyi[entry] : carry_d((uint64_t)crowd_skin_ij(w, h, m, g, lv, lo > i), dyi[entry]);
                const wide pv = div_nearest_by(mulu64_128(w.ce[hg * w.slots + jj], cy), cdiv[warp][jj]);
                add_wide(w.cv + (first + r + lo) * S + entry, pv);
                add_wide(w.cv + (first + r + hi_ + 1) * S + entry, -pv);
            }
        }
        sum = parts_sum(active ? sum : 0, S, parts);
        if (lane < S) {
            const uint32_t mc = h * n + lane % n;
            const uint64_t slot = g * w.M2 + (lane < n ? mc : w.M + mc);
            const int64_t probe_role = fit64(rel(sum, CONTACT_BACK + g0), w.status);
            // The probe role goes to the probe chart's covector, the key role (the columns) to the key's (§16.19).
            w.dp[slot] = probe_role;
            dq[slot] = 0;
        }
        __syncwarp();
    }
}

// field_contact_rows, mechanism r
extern "C" __global__ void __launch_bounds__(REV_ROWS * 32, 4) field_copy_r_contact_rows(FieldWords w, uint32_t h, const int64_t *dyh, int64_t *ds, int64_t *dq) {
    __shared__ uint32_t stj[REV_ROWS][32], stk[REV_ROWS][32];
    __shared__ int64_t dss[REV_ROWS][32];
    __shared__ wide dpcs[REV_ROWS][MAX_CROWD_SLOTS];
    __shared__ int64_t dsks[REV_ROWS][MAX_CROWD_SLOTS];
    __shared__ uint64_t cnts[REV_ROWS][32];
    __shared__ uint32_t crlo[REV_ROWS][32], crhi[REV_ROWS][32], crlv[REV_ROWS][32];
    __shared__ Divisor cdiv[REV_ROWS][32], cdiv2[REV_ROWS][32];
    __shared__ RowCls rcs[REV_ROWS];
    const uint32_t warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const uint32_t parts = span_parts(S);
    const bool active = lane < S * parts;
    const uint32_t entry = lane % S, part = lane / S, m = entry % n;
    const wide ln2 = (wide)(((uwide)w.ln2_hi << 64) | (uwide)w.ln2_lo);
    const bool still = skinless(w, h);
    const uint32_t g0 = still ? 0 : MOVE_BITS;
    const uint64_t rows1 = (uint64_t)w.T + w.R;
    for (uint64_t g = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; g < w.T; g += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint64_t hg = (uint64_t)h * w.T + g;
        if (skipped_row(w, g)) {
            if (lane < S) {
                const uint32_t mc = h * n + lane % n;
                const uint64_t slot = g * w.M2 + (lane < n ? mc : w.M + mc);
                w.dp[slot] = 0;
                dq[slot] = 0;
            }
            continue;
        }
        const uint32_t r = w.site_region[g];
        const uint32_t i = w.site_pos[g];
        const uint64_t first = w.region_off[r];
        const uint32_t sites = w.region_off[r + 1] - (uint32_t)first;
        const uint32_t *members = w.members + (uint64_t)h * w.T + first;
        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t c = w.cls[hg];
        const uint32_t K = row_prepare(w, hg, off, rcs[warp], lane);
        const uint64_t *e = w.e + (uint64_t)h * w.E + w.region_eoff[r] + (uint64_t)i * sites;
        int64_t *dsr = ds + w.region_eoff[r] + (uint64_t)i * sites;
        wide *dpr = w.dpb + w.region_eoff[r] + (uint64_t)i * sites;
        // The row's support entries' addresses (the clock's skins stand there).
        const uint64_t srow = support_row(w, r, i);
        const int64_t *dyi = dyh + hg * S;
        const int64_t *values = w.vf + ((uint64_t)h * w.T + first) * S;
        const int64_t *words = w.qf + ((uint64_t)h * w.T + first) * S;
        const uint64_t prow0 = (uint64_t)h * rows1 + first + r;
        const wide *swp = w.sw + prow0 * S;
        const wide *svp = w.sv + prow0 * S;
        const uint64_t *scp = w.sc + prow0;
        const uint32_t nslots = rcs[warp].open ? 0 : crowd_slots(sites);
        const wide temper = temper_of(w, h, rcs[warp].open != 0);
        const int64_t *sbr = w.sb + (uint64_t)h * w.E + w.region_eoff[r] + (uint64_t)i * sites;
        // The pair's covector `⟨δỹ_i, D ṽ_j⟩` on `2^(−40)`.
        const auto pair_dp = [&](uint32_t j, uint32_t k, uint32_t gap) -> wide {
            const int64_t *vj = values + (uint64_t)i * S;
            wide dp = 0;
            for (uint32_t x = 0; x < S; x++) {
                // [P54 step 4] The carried value is under `2^63` (`D ≤ 2^30`): the covector's product is 64 by 64.
                dp += mul64_128(dyi[x], (int64_t)carried_ij_at(w, h, x % n, g, srow + k, gap, vj[x]));
            }
            return dp;
        };
        // The same for a head of eight modes, from vector rows: the source's sixteen values as eight 16-octet loads
        // and its skins as two (`pair_score8`).
        const bool eight = w.n == 8;
        const bool still_h = skinless(w, h), paced_h = paced_at(w, h, g);
        const auto pair_dp8 = [&](uint32_t j, uint32_t k, uint32_t gap) -> wide {
            const longlong2 *v2 = reinterpret_cast<const longlong2 *>(values + (uint64_t)i * S);
            uint32_t dec[8];
            if (still_h) {
#pragma unroll
                for (int l = 0; l < 8; l++) {
                    dec[l] = 1;
                }
            } else if (paced_h) {
                pair_skins8(w, paced_index(w, h), srow + k, dec);
            } else {
                const uint4 *d4 = reinterpret_cast<const uint4 *>(w.decay_t + ((uint64_t)h * w.dreach + gap) * 8);
                const uint4 d0 = d4[0], d1 = d4[1];
                dec[0] = d0.x; dec[1] = d0.y; dec[2] = d0.z; dec[3] = d0.w;
                dec[4] = d1.x; dec[5] = d1.y; dec[6] = d1.z; dec[7] = d1.w;
            }
            wide dp = 0;
#pragma unroll
            for (int q = 0; q < 8; q++) {
                const longlong2 t = v2[q];
                dp += mul64_128(dyi[2 * q], still_h ? t.x : carry_d(dec[(2 * q) & 7], t.x));
                dp += mul64_128(dyi[2 * q + 1], still_h ? t.y : carry_d(dec[(2 * q + 1) & 7], t.y));
            }
            return dp;
        };
        // The crowds: counts, places and their divisors.
        {
            uint64_t count = 0;
            uint32_t lo = 0, hi_ = 0, lv = 0;
            if (lane < nslots && crowd_at(i, sites, lane, &lo, &hi_, &lv)) {
                count = scp[hi_ + 1] - scp[lo];
            }
            cnts[warp][lane] = count;
            crlo[warp][lane] = lo;
            crhi[warp][lane] = hi_;
            crlv[warp][lane] = lv;
            if (count != 0) {
                cdiv[warp][lane] = divisor_of(count);
                cdiv2[warp][lane] = divisor_of(count * count);
            }
        }
        __syncwarp();
        // Pass A: the weighted sum of the pairs' and crowds' covectors.
        wide weighted = 0;
        for (uint32_t k = lane; k < K; k += 32) {
            const uint32_t j = support_at(members, off, rcs[warp], i, sites, k);
            if (j == UINT32_MAX) {
                continue;
            }
            const wide p = (wide)e[j];
            const uint32_t gap = j > i ? j - i : i - j;
            const wide dpj = eight ? pair_dp8(j, k, gap) : pair_dp(j, k, gap);
            dpr[j] = dpj;
            weighted += p * dpj;
        }
        if (cnts[warp][lane] != 0) {
            const uint32_t lo = crlo[warp][lane], hi_ = crhi[warp][lane], lv = crlv[warp][lane];
            wide sum = 0;
            for (uint32_t x = 0; x < S; x++) {
                sum += (wide)dyi[x] * crowd_carried_wide_ij(w, h, x % n, g, lv, lo > i, svp[(uint64_t)(hi_ + 1) * S + x] - svp[(uint64_t)lo * S + x]);
            }
            const wide dpc = div_nearest_by(sum, cdiv[warp][lane]);
            dpcs[warp][lane] = dpc;
            weighted += (wide)w.ce[hg * w.slots + lane] * dpc;
        }
        const wide mean = rel(warp_sum(weighted), SHARE_BITS);
        // The comparison of a term `p` (its covector `dpk`): the face's.
        const auto compare = [&](wide p, wide dpk) -> wide { return rel(ln2 * rel(p * (dpk - mean), SHARE_BITS), MOVE_BITS); };
        // Pass B: δs over the pairs, in chunks of 32 into the warp's shared chunk, whose sum over the word is
        // read with the lanes over the span's entries (the probe role: `δs D ŵ_j`).
        wide sum = 0;
        // The temperature's covector (§15.10): `δT[h][kind] += release(δz S, 16)` over the row's sources and crowds,
        // each released alone and summed (an exact integer sum, the lanes' partials added over the warp).
        wide tacc = 0;
        // The covector's magnitude near and far (§16.20), where read.
        wide near_ds = 0, far_ds = 0;
        for (uint32_t k0 = 0; k0 < K; k0 += 32) {
            const uint32_t k = k0 + lane;
            const uint32_t j = k < K ? support_at(members, off, rcs[warp], i, sites, k) : UINT32_MAX;
            int64_t dsv = 0;
            if (j != UINT32_MAX) {
                const wide dzj = compare((wide)e[j], dpr[j]);
                tacc += rel(dzj * (wide)sbr[j], FACE_BITS);
                const wide dz = rel(temper * dzj, MATERIAL_BITS);
                if ((dz < 0 ? -dz : dz) >> min(w.dsbits, 63u) != 0) {
                    atomicOr(w.status, REFUSED_CARRIER);
                }
                dsv = (int64_t)dz;
                dsr[j] = dsv;
                const wide mag = dz < 0 ? -dz : dz;
                if ((j > i ? j - i : i - j) < NEAR) {
                    near_ds += mag;
                } else {
                    far_ds += mag;
                }
            }
            dss[warp][lane] = dsv;
            stj[warp][lane] = j;
            stk[warp][lane] = k;
            __syncwarp();
            if (active) {
                for (uint32_t jj = part; jj < 32; jj += parts) {
                    const uint32_t jx = stj[warp][jj];
                    if (jx != UINT32_MAX) {
                        // [P54 step 4] `δs (D ŵ_j)`: the skin and the unit word on 32 bits (their product under `2^61`), then 64 by 64.
                        sum += mul64_128(dss[warp][jj], mul32((int64_t)skin_raw_at(w, h, m, g, srow + stk[warp][jj], jx > i ? jx - i : i - jx), words[(uint64_t)i * S + entry]));
                    }
                }
            }
            __syncwarp();
        }
        // The crowds' δs, then their share of the row's return and of the values' and the word's member
        // returns through the difference arrays.
        if (cnts[warp][lane] != 0) {
            const wide dzc = compare((wide)w.ce[hg * w.slots + lane], dpcs[warp][lane]);
            const uint32_t clo = crlo[warp][lane], chi = crhi[warp][lane], clv = crlv[warp][lane];
            const int64_t cs = crowd_base_narrow(w, h, w.pq + ((uint64_t)h * w.T + g) * S, swp + (uint64_t)clo * S, swp + (uint64_t)(chi + 1) * S, cnts[warp][lane], clv, g, clo > i);
            tacc += rel(dzc * (wide)cs, FACE_BITS);
            const wide dz = rel(temper * dzc, MATERIAL_BITS);
            if ((dz < 0 ? -dz : dz) >> min(w.dsbits, 63u) != 0) {
                atomicOr(w.status, REFUSED_CARRIER);
            }
            dsks[warp][lane] = (int64_t)dz;
            if (w.cds != nullptr) {
                w.cds[hg * w.slots + lane] = (int64_t)dz;
            }
            far_ds += dz < 0 ? -dz : dz;
        }
        if (w.dsshare != nullptr) {
            near_ds = warp_sum(near_ds);
            far_ds = warp_sum(far_ds);
            if (lane == 0) {
                add_wide(w.dsshare + 2 * h, near_ds);
                add_wide(w.dsshare + 2 * h + 1, far_ds);
            }
        }
        tacc = warp_sum(tacc);
        if (lane == 0 && tacc != 0) {
            // Into the temperature's own chart (§16.12): `δℓ = release(δT · release(T ln 2, 30), 24)`, the row's.
            add_wide(w.gcov + w.temper_at + 2 * h + (rcs[warp].open ? 1 : 0), temper_chain(w, temper, tacc));
        }
        __syncwarp();
        if (active) {
            for (uint32_t jj = part; jj < nslots; jj += parts) {
                const uint64_t count = cnts[warp][jj];
                if (count == 0) {
                    continue;
                }
                const uint32_t lo = crlo[warp][jj], hi_ = crhi[warp][jj], lv = crlv[warp][jj];
                const wide d = crowd_skin_raw(w, h, m, g, lv, lo > i);
                const wide dsk = dsks[warp][jj];
                const wide wsum = swp[(uint64_t)(hi_ + 1) * S + entry] - swp[(uint64_t)lo * S + entry];
                // [P54 step 4] Where the crowd's summed word is under `2^31`: `D W`, `D ŵ_i` and `D²` on 32 bits (under `2^61`), their
                // products by the covector, the count and `W` as 64 by 64; otherwise the wide forms.
                int32_t w32;
                wide bracket;
                if (narrow31(wsum, &w32)) {
                    sum += div_nearest_by(mul64_128(dsks[warp][jj], mul32((int64_t)d, w32)), cdiv[warp][jj]);
                    // The key's bracket released by the skin's bits once, its product by the covector checked.
                    bracket = rel((mul64_128(mul32((int64_t)d, w.pq[((uint64_t)h * w.T + g) * S + entry]), (int64_t)count) << g0) - mul64_128(mul32((int64_t)d, (int64_t)d), w32), g0);
                } else {
                    RULER_LONG();
                    sum += div_nearest_by(dsk * d * wsum, cdiv[warp][jj]);
                    bracket = rel(((d * (wide)w.pq[((uint64_t)h * w.T + g) * S + entry] * (wide)count) << g0) - d * d * wsum, g0);
                }
                wide prod = 0;
                if (!mul_fits(dsk, bracket, &prod)) {
                    atomicOr(w.status, REFUSED_KEY);
                }
                const wide pw = div_nearest_by(prod, cdiv2[warp][jj]);
                add_wide(w.cw + (first + r + lo) * S + entry, pw);
                add_wide(w.cw + (first + r + hi_ + 1) * S + entry, -pw);
                // [P54 step 4] The carried covector `release(D δỹ, 30)` on 64 bits (`carry_d`, under `2^63`), its share's product unsigned by signed.
                const int64_t cy = still ? dyi[entry] : carry_d((uint64_t)crowd_skin_ij(w, h, m, g, lv, lo > i), dyi[entry]);
                const wide pv = div_nearest_by(mulu64_128(w.ce[hg * w.slots + jj], cy), cdiv[warp][jj]);
                add_wide(w.cv + (first + r + lo) * S + entry, pv);
                add_wide(w.cv + (first + r + hi_ + 1) * S + entry, -pv);
            }
        }
        sum = parts_sum(active ? sum : 0, S, parts);
        if (lane < S) {
            const uint32_t mc = h * n + lane % n;
            const uint64_t slot = g * w.M2 + (lane < n ? mc : w.M + mc);
            const int64_t probe_role = fit64(rel(sum, CONTACT_BACK + g0), w.status);
            // The probe role goes to the probe chart's covector, the key role (the columns) to the key's (§16.19).
            w.dp[slot] = probe_role;
            dq[slot] = 0;
        }
        __syncwarp();
    }
}

// field_contact_rows, mechanism w
extern "C" __global__ void __launch_bounds__(REV_ROWS * 32, 4) field_copy_w_contact_rows(FieldWords w, uint32_t h, const int64_t *dyh, int64_t *ds, int64_t *dq) {
    __shared__ uint32_t stj[REV_ROWS][32], stk[REV_ROWS][32];
    __shared__ int64_t dss[REV_ROWS][32];
    __shared__ wide dpcs[REV_ROWS][MAX_CROWD_SLOTS];
    __shared__ int64_t dsks[REV_ROWS][MAX_CROWD_SLOTS];
    __shared__ uint64_t cnts[REV_ROWS][32];
    __shared__ uint32_t crlo[REV_ROWS][32], crhi[REV_ROWS][32], crlv[REV_ROWS][32];
    __shared__ Divisor cdiv[REV_ROWS][32], cdiv2[REV_ROWS][32];
    __shared__ RowCls rcs[REV_ROWS];
    const uint32_t warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const uint32_t parts = span_parts(S);
    const bool active = lane < S * parts;
    const uint32_t entry = lane % S, part = lane / S, m = entry % n;
    const wide ln2 = (wide)(((uwide)w.ln2_hi << 64) | (uwide)w.ln2_lo);
    const bool still = skinless(w, h);
    const uint32_t g0 = still ? 0 : MOVE_BITS;
    const uint64_t rows1 = (uint64_t)w.T + w.R;
    for (uint64_t g = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; g < w.T; g += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint64_t hg = (uint64_t)h * w.T + g;
        if (skipped_row(w, g)) {
            if (lane < S) {
                const uint32_t mc = h * n + lane % n;
                const uint64_t slot = g * w.M2 + (lane < n ? mc : w.M + mc);
                w.dp[slot] = 0;
                dq[slot] = 0;
            }
            continue;
        }
        const uint32_t r = w.site_region[g];
        const uint32_t i = w.site_pos[g];
        const uint64_t first = w.region_off[r];
        const uint32_t sites = w.region_off[r + 1] - (uint32_t)first;
        const uint32_t *members = w.members + (uint64_t)h * w.T + first;
        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t c = w.cls[hg];
        const uint32_t K = row_prepare(w, hg, off, rcs[warp], lane);
        const uint64_t *e = w.e + (uint64_t)h * w.E + w.region_eoff[r] + (uint64_t)i * sites;
        int64_t *dsr = ds + w.region_eoff[r] + (uint64_t)i * sites;
        wide *dpr = w.dpb + w.region_eoff[r] + (uint64_t)i * sites;
        // The row's support entries' addresses (the clock's skins stand there).
        const uint64_t srow = support_row(w, r, i);
        const int64_t *dyi = dyh + hg * S;
        const int64_t *values = w.vf + ((uint64_t)h * w.T + first) * S;
        const int64_t *words = w.qf + ((uint64_t)h * w.T + first) * S;
        const uint64_t prow0 = (uint64_t)h * rows1 + first + r;
        const wide *swp = w.sw + prow0 * S;
        const wide *svp = w.sv + prow0 * S;
        const uint64_t *scp = w.sc + prow0;
        const uint32_t nslots = rcs[warp].open ? 0 : crowd_slots(sites);
        const wide temper = temper_of(w, h, rcs[warp].open != 0);
        const int64_t *sbr = w.sb + (uint64_t)h * w.E + w.region_eoff[r] + (uint64_t)i * sites;
        // The pair's covector `⟨δỹ_i, D ṽ_j⟩` on `2^(−40)`.
        const auto pair_dp = [&](uint32_t j, uint32_t k, uint32_t gap) -> wide {
            const int64_t *vj = values + (uint64_t)j * S;
            wide dp = 0;
            for (uint32_t x = 0; x < S; x++) {
                // [P54 step 4] The carried value is under `2^63` (`D ≤ 2^30`): the covector's product is 64 by 64.
                dp += mul64_128(dyi[x], (int64_t)carried_ij_at(w, h, x % n, g, srow + k, gap, vj[x]));
            }
            return dp;
        };
        // The same for a head of eight modes, from vector rows: the source's sixteen values as eight 16-octet loads
        // and its skins as two (`pair_score8`).
        const bool eight = w.n == 8;
        const bool still_h = skinless(w, h), paced_h = paced_at(w, h, g);
        const auto pair_dp8 = [&](uint32_t j, uint32_t k, uint32_t gap) -> wide {
            const longlong2 *v2 = reinterpret_cast<const longlong2 *>(values + (uint64_t)j * S);
            uint32_t dec[8];
            if (still_h) {
#pragma unroll
                for (int l = 0; l < 8; l++) {
                    dec[l] = 1;
                }
            } else if (paced_h) {
                pair_skins8(w, paced_index(w, h), srow + k, dec);
            } else {
                const uint4 *d4 = reinterpret_cast<const uint4 *>(w.decay_t + ((uint64_t)h * w.dreach + gap) * 8);
                const uint4 d0 = d4[0], d1 = d4[1];
                dec[0] = d0.x; dec[1] = d0.y; dec[2] = d0.z; dec[3] = d0.w;
                dec[4] = d1.x; dec[5] = d1.y; dec[6] = d1.z; dec[7] = d1.w;
            }
            wide dp = 0;
#pragma unroll
            for (int q = 0; q < 8; q++) {
                const longlong2 t = v2[q];
                dp += mul64_128(dyi[2 * q], still_h ? t.x : carry_d(dec[(2 * q) & 7], t.x));
                dp += mul64_128(dyi[2 * q + 1], still_h ? t.y : carry_d(dec[(2 * q + 1) & 7], t.y));
            }
            return dp;
        };
        // The crowds: counts, places and their divisors.
        {
            uint64_t count = 0;
            uint32_t lo = 0, hi_ = 0, lv = 0;
            if (lane < nslots && crowd_at(i, sites, lane, &lo, &hi_, &lv)) {
                count = scp[hi_ + 1] - scp[lo];
            }
            cnts[warp][lane] = count;
            crlo[warp][lane] = lo;
            crhi[warp][lane] = hi_;
            crlv[warp][lane] = lv;
            if (count != 0) {
                cdiv[warp][lane] = divisor_of(count);
                cdiv2[warp][lane] = divisor_of(count * count);
            }
        }
        __syncwarp();
        // Pass A: the weighted sum of the pairs' and crowds' covectors.
        wide weighted = 0;
        for (uint32_t k = lane; k < K; k += 32) {
            const uint32_t j = support_at(members, off, rcs[warp], i, sites, k);
            if (j == UINT32_MAX) {
                continue;
            }
            const wide p = (wide)e[k % sites];
            const uint32_t gap = j > i ? j - i : i - j;
            const wide dpj = eight ? pair_dp8(j, k, gap) : pair_dp(j, k, gap);
            dpr[k % sites] = dpj;
            weighted += p * dpj;
        }
        if (cnts[warp][lane] != 0) {
            const uint32_t lo = crlo[warp][lane], hi_ = crhi[warp][lane], lv = crlv[warp][lane];
            wide sum = 0;
            for (uint32_t x = 0; x < S; x++) {
                sum += (wide)dyi[x] * crowd_carried_wide_ij(w, h, x % n, g, lv, lo > i, svp[(uint64_t)(hi_ + 1) * S + x] - svp[(uint64_t)lo * S + x]);
            }
            const wide dpc = div_nearest_by(sum, cdiv[warp][lane]);
            dpcs[warp][lane] = dpc;
            weighted += (wide)w.ce[hg * w.slots + lane] * dpc;
        }
        const wide mean = rel(warp_sum(weighted), SHARE_BITS);
        // The comparison of a term `p` (its covector `dpk`): the face's.
        const auto compare = [&](wide p, wide dpk) -> wide { return rel(ln2 * rel(p * (dpk - mean), SHARE_BITS), MOVE_BITS); };
        // Pass B: δs over the pairs, in chunks of 32 into the warp's shared chunk, whose sum over the word is
        // read with the lanes over the span's entries (the probe role: `δs D ŵ_j`).
        wide sum = 0;
        // The temperature's covector (§15.10): `δT[h][kind] += release(δz S, 16)` over the row's sources and crowds,
        // each released alone and summed (an exact integer sum, the lanes' partials added over the warp).
        wide tacc = 0;
        // The covector's magnitude near and far (§16.20), where read.
        wide near_ds = 0, far_ds = 0;
        for (uint32_t k0 = 0; k0 < K; k0 += 32) {
            const uint32_t k = k0 + lane;
            const uint32_t j = k < K ? support_at(members, off, rcs[warp], i, sites, k) : UINT32_MAX;
            int64_t dsv = 0;
            if (j != UINT32_MAX) {
                const wide dzj = compare((wide)e[k % sites], dpr[k % sites]);
                tacc += rel(dzj * (wide)sbr[k % sites], FACE_BITS);
                const wide dz = rel(temper * dzj, MATERIAL_BITS);
                if ((dz < 0 ? -dz : dz) >> min(w.dsbits, 63u) != 0) {
                    atomicOr(w.status, REFUSED_CARRIER);
                }
                dsv = (int64_t)dz;
                dsr[k % sites] = dsv;
                const wide mag = dz < 0 ? -dz : dz;
                if ((j > i ? j - i : i - j) < NEAR) {
                    near_ds += mag;
                } else {
                    far_ds += mag;
                }
            }
            dss[warp][lane] = dsv;
            stj[warp][lane] = j;
            stk[warp][lane] = k;
            __syncwarp();
            if (active) {
                for (uint32_t jj = part; jj < 32; jj += parts) {
                    const uint32_t jx = stj[warp][jj];
                    if (jx != UINT32_MAX) {
                        // [P54 step 4] `δs (D ŵ_j)`: the skin and the unit word on 32 bits (their product under `2^61`), then 64 by 64.
                        sum += mul64_128(dss[warp][jj], mul32((int64_t)skin_raw_at(w, h, m, g, srow + stk[warp][jj], jx > i ? jx - i : i - jx), words[(uint64_t)jx * S + entry]));
                    }
                }
            }
            __syncwarp();
        }
        // The crowds' δs, then their share of the row's return and of the values' and the word's member
        // returns through the difference arrays.
        if (cnts[warp][lane] != 0) {
            const wide dzc = compare((wide)w.ce[hg * w.slots + lane], dpcs[warp][lane]);
            const uint32_t clo = crlo[warp][lane], chi = crhi[warp][lane], clv = crlv[warp][lane];
            const int64_t cs = crowd_base_narrow(w, h, w.pq + ((uint64_t)h * w.T + g) * S, swp + (uint64_t)clo * S, swp + (uint64_t)(chi + 1) * S, cnts[warp][lane], clv, g, clo > i);
            tacc += rel(dzc * (wide)cs, FACE_BITS);
            const wide dz = rel(temper * dzc, MATERIAL_BITS);
            if ((dz < 0 ? -dz : dz) >> min(w.dsbits, 63u) != 0) {
                atomicOr(w.status, REFUSED_CARRIER);
            }
            dsks[warp][lane] = (int64_t)dz;
            if (w.cds != nullptr) {
                w.cds[hg * w.slots + lane] = (int64_t)dz;
            }
            far_ds += dz < 0 ? -dz : dz;
        }
        if (w.dsshare != nullptr) {
            near_ds = warp_sum(near_ds);
            far_ds = warp_sum(far_ds);
            if (lane == 0) {
                add_wide(w.dsshare + 2 * h, near_ds);
                add_wide(w.dsshare + 2 * h + 1, far_ds);
            }
        }
        tacc = warp_sum(tacc);
        if (lane == 0 && tacc != 0) {
            // Into the temperature's own chart (§16.12): `δℓ = release(δT · release(T ln 2, 30), 24)`, the row's.
            add_wide(w.gcov + w.temper_at + 2 * h + (rcs[warp].open ? 1 : 0), temper_chain(w, temper, tacc));
        }
        __syncwarp();
        if (active) {
            for (uint32_t jj = part; jj < nslots; jj += parts) {
                const uint64_t count = cnts[warp][jj];
                if (count == 0) {
                    continue;
                }
                const uint32_t lo = crlo[warp][jj], hi_ = crhi[warp][jj], lv = crlv[warp][jj];
                const wide d = crowd_skin_raw(w, h, m, g, lv, lo > i);
                const wide dsk = dsks[warp][jj];
                const wide wsum = swp[(uint64_t)(hi_ + 1) * S + entry] - swp[(uint64_t)lo * S + entry];
                // [P54 step 4] Where the crowd's summed word is under `2^31`: `D W`, `D ŵ_i` and `D²` on 32 bits (under `2^61`), their
                // products by the covector, the count and `W` as 64 by 64; otherwise the wide forms.
                int32_t w32;
                wide bracket;
                if (narrow31(wsum, &w32)) {
                    sum += div_nearest_by(mul64_128(dsks[warp][jj], mul32((int64_t)d, w32)), cdiv[warp][jj]);
                    // The key's bracket released by the skin's bits once, its product by the covector checked.
                    bracket = rel((mul64_128(mul32((int64_t)d, w.pq[((uint64_t)h * w.T + g) * S + entry]), (int64_t)count) << g0) - mul64_128(mul32((int64_t)d, (int64_t)d), w32), g0);
                } else {
                    RULER_LONG();
                    sum += div_nearest_by(dsk * d * wsum, cdiv[warp][jj]);
                    bracket = rel(((d * (wide)w.pq[((uint64_t)h * w.T + g) * S + entry] * (wide)count) << g0) - d * d * wsum, g0);
                }
                wide prod = 0;
                if (!mul_fits(dsk, bracket, &prod)) {
                    atomicOr(w.status, REFUSED_KEY);
                }
                const wide pw = div_nearest_by(prod, cdiv2[warp][jj]);
                add_wide(w.cw + (first + r + lo) * S + entry, pw);
                add_wide(w.cw + (first + r + hi_ + 1) * S + entry, -pw);
                // [P54 step 4] The carried covector `release(D δỹ, 30)` on 64 bits (`carry_d`, under `2^63`), its share's product unsigned by signed.
                const int64_t cy = still ? dyi[entry] : carry_d((uint64_t)crowd_skin_ij(w, h, m, g, lv, lo > i), dyi[entry]);
                const wide pv = div_nearest_by(mulu64_128(w.ce[hg * w.slots + jj], cy), cdiv[warp][jj]);
                add_wide(w.cv + (first + r + lo) * S + entry, pv);
                add_wide(w.cv + (first + r + hi_ + 1) * S + entry, -pv);
            }
        }
        sum = parts_sum(active ? sum : 0, S, parts);
        if (lane < S) {
            const uint32_t mc = h * n + lane % n;
            const uint64_t slot = g * w.M2 + (lane < n ? mc : w.M + mc);
            const int64_t probe_role = fit64(rel(sum, CONTACT_BACK + g0), w.status);
            // The probe role goes to the probe chart's covector, the key role (the columns) to the key's (§16.19).
            w.dp[slot] = probe_role;
            dq[slot] = 0;
        }
        __syncwarp();
    }
}

// field_contact_rows, mechanism a
extern "C" __global__ void __launch_bounds__(REV_ROWS * 32, 4) field_copy_a_contact_rows(FieldWords w, uint32_t h, const int64_t *dyh, int64_t *ds, int64_t *dq, wide *plain) {
    __shared__ uint32_t stj[REV_ROWS][32], stk[REV_ROWS][32];
    __shared__ int64_t dss[REV_ROWS][32];
    __shared__ wide dpcs[REV_ROWS][MAX_CROWD_SLOTS];
    __shared__ int64_t dsks[REV_ROWS][MAX_CROWD_SLOTS];
    __shared__ uint64_t cnts[REV_ROWS][32];
    __shared__ uint32_t crlo[REV_ROWS][32], crhi[REV_ROWS][32], crlv[REV_ROWS][32];
    __shared__ Divisor cdiv[REV_ROWS][32], cdiv2[REV_ROWS][32];
    __shared__ RowCls rcs[REV_ROWS];
    const uint32_t warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const uint32_t parts = span_parts(S);
    const bool active = lane < S * parts;
    const uint32_t entry = lane % S, part = lane / S, m = entry % n;
    const wide ln2 = (wide)(((uwide)w.ln2_hi << 64) | (uwide)w.ln2_lo);
    const bool still = skinless(w, h);
    const uint32_t g0 = still ? 0 : MOVE_BITS;
    const uint64_t rows1 = (uint64_t)w.T + w.R;
    for (uint64_t g = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; g < w.T; g += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint64_t hg = (uint64_t)h * w.T + g;
        if (skipped_row(w, g)) {
            if (lane < S) {
                const uint32_t mc = h * n + lane % n;
                const uint64_t slot = g * w.M2 + (lane < n ? mc : w.M + mc);
                w.dp[slot] = 0;
                dq[slot] = 0;
            }
            continue;
        }
        const uint32_t r = w.site_region[g];
        const uint32_t i = w.site_pos[g];
        const uint64_t first = w.region_off[r];
        const uint32_t sites = w.region_off[r + 1] - (uint32_t)first;
        const uint32_t *members = w.members + (uint64_t)h * w.T + first;
        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t c = w.cls[hg];
        const uint32_t K = row_prepare(w, hg, off, rcs[warp], lane);
        const uint64_t *e = w.e + (uint64_t)h * w.E + w.region_eoff[r] + (uint64_t)i * sites;
        int64_t *dsr = ds + w.region_eoff[r] + (uint64_t)i * sites;
        wide *dpr = w.dpb + w.region_eoff[r] + (uint64_t)i * sites;
        // The row's support entries' addresses (the clock's skins stand there).
        const uint64_t srow = support_row(w, r, i);
        const int64_t *dyi = dyh + hg * S;
        const int64_t *values = w.vf + ((uint64_t)h * w.T + first) * S;
        const int64_t *words = w.qf + ((uint64_t)h * w.T + first) * S;
        const uint64_t prow0 = (uint64_t)h * rows1 + first + r;
        const wide *swp = w.sw + prow0 * S;
        const wide *svp = w.sv + prow0 * S;
        const uint64_t *scp = w.sc + prow0;
        const uint32_t nslots = rcs[warp].open ? 0 : crowd_slots(sites);
        const wide temper = temper_of(w, h, rcs[warp].open != 0);
        const int64_t *sbr = w.sb + (uint64_t)h * w.E + w.region_eoff[r] + (uint64_t)i * sites;
        // The pair's covector `⟨δỹ_i, D ṽ_j⟩` on `2^(−40)`.
        const auto pair_dp = [&](uint32_t j, uint32_t k, uint32_t gap) -> wide {
            const int64_t *vj = values + (uint64_t)j * S;
            wide dp = 0;
            for (uint32_t x = 0; x < S; x++) {
                // [P54 step 4] The carried value is under `2^63` (`D ≤ 2^30`): the covector's product is 64 by 64.
                dp += mul64_128(dyi[x], (int64_t)carried_ij_at(w, h, x % n, g, srow + k, gap, vj[x]));
            }
            return dp;
        };
        // The same for a head of eight modes, from vector rows: the source's sixteen values as eight 16-octet loads
        // and its skins as two (`pair_score8`).
        const bool eight = w.n == 8;
        const bool still_h = skinless(w, h), paced_h = paced_at(w, h, g);
        const auto pair_dp8 = [&](uint32_t j, uint32_t k, uint32_t gap) -> wide {
            const longlong2 *v2 = reinterpret_cast<const longlong2 *>(values + (uint64_t)j * S);
            uint32_t dec[8];
            if (still_h) {
#pragma unroll
                for (int l = 0; l < 8; l++) {
                    dec[l] = 1;
                }
            } else if (paced_h) {
                pair_skins8(w, paced_index(w, h), srow + k, dec);
            } else {
                const uint4 *d4 = reinterpret_cast<const uint4 *>(w.decay_t + ((uint64_t)h * w.dreach + gap) * 8);
                const uint4 d0 = d4[0], d1 = d4[1];
                dec[0] = d0.x; dec[1] = d0.y; dec[2] = d0.z; dec[3] = d0.w;
                dec[4] = d1.x; dec[5] = d1.y; dec[6] = d1.z; dec[7] = d1.w;
            }
            wide dp = 0;
#pragma unroll
            for (int q = 0; q < 8; q++) {
                const longlong2 t = v2[q];
                dp += mul64_128(dyi[2 * q], still_h ? t.x : carry_d(dec[(2 * q) & 7], t.x));
                dp += mul64_128(dyi[2 * q + 1], still_h ? t.y : carry_d(dec[(2 * q + 1) & 7], t.y));
            }
            return dp;
        };
        // The crowds: counts, places and their divisors.
        {
            uint64_t count = 0;
            uint32_t lo = 0, hi_ = 0, lv = 0;
            if (lane < nslots && crowd_at(i, sites, lane, &lo, &hi_, &lv)) {
                count = scp[hi_ + 1] - scp[lo];
            }
            cnts[warp][lane] = count;
            crlo[warp][lane] = lo;
            crhi[warp][lane] = hi_;
            crlv[warp][lane] = lv;
            if (count != 0) {
                cdiv[warp][lane] = divisor_of(count);
                cdiv2[warp][lane] = divisor_of(count * count);
            }
        }
        __syncwarp();
        // Pass A: the weighted sum of the pairs' and crowds' covectors.
        wide weighted = 0;
        for (uint32_t k = lane; k < K; k += 32) {
            const uint32_t j = support_at(members, off, rcs[warp], i, sites, k);
            if (j == UINT32_MAX) {
                continue;
            }
            const wide p = (wide)e[j];
            const uint32_t gap = j > i ? j - i : i - j;
            const wide dpj = eight ? pair_dp8(j, k, gap) : pair_dp(j, k, gap);
            dpr[j] = dpj;
            weighted += p * dpj;
        }
        if (cnts[warp][lane] != 0) {
            const uint32_t lo = crlo[warp][lane], hi_ = crhi[warp][lane], lv = crlv[warp][lane];
            wide sum = 0;
            for (uint32_t x = 0; x < S; x++) {
                sum += (wide)dyi[x] * crowd_carried_wide_ij(w, h, x % n, g, lv, lo > i, svp[(uint64_t)(hi_ + 1) * S + x] - svp[(uint64_t)lo * S + x]);
            }
            const wide dpc = div_nearest_by(sum, cdiv[warp][lane]);
            dpcs[warp][lane] = dpc;
            weighted += (wide)w.ce[hg * w.slots + lane] * dpc;
        }
        const wide mean = rel(warp_sum(weighted), SHARE_BITS);
        // The comparison of a term `p` (its covector `dpk`): the face's.
        const auto compare = [&](wide p, wide dpk) -> wide { return rel(ln2 * rel(p * (dpk - mean), SHARE_BITS), MOVE_BITS); };
        // Pass B: δs over the pairs, in chunks of 32 into the warp's shared chunk, whose sum over the word is
        // read with the lanes over the span's entries (the probe role: `δs D ŵ_j`).
        wide sum = 0;
        // The temperature's covector (§15.10): `δT[h][kind] += release(δz S, 16)` over the row's sources and crowds,
        // each released alone and summed (an exact integer sum, the lanes' partials added over the warp).
        wide tacc = 0;
        // The covector's magnitude near and far (§16.20), where read.
        wide near_ds = 0, far_ds = 0;
        for (uint32_t k0 = 0; k0 < K; k0 += 32) {
            const uint32_t k = k0 + lane;
            const uint32_t j = k < K ? support_at(members, off, rcs[warp], i, sites, k) : UINT32_MAX;
            int64_t dsv = 0;
            if (j != UINT32_MAX) {
                const wide dzj = compare((wide)e[j], dpr[j]);
                tacc += rel(dzj * (wide)sbr[j], FACE_BITS);
                const wide dz = rel(temper * dzj, MATERIAL_BITS);
                if ((dz < 0 ? -dz : dz) >> min(w.dsbits, 63u) != 0) {
                    atomicOr(w.status, REFUSED_CARRIER);
                }
                dsv = (int64_t)dz;
                dsr[j] = dsv;
                const wide mag = dz < 0 ? -dz : dz;
                if ((j > i ? j - i : i - j) < NEAR) {
                    near_ds += mag;
                } else {
                    far_ds += mag;
                }
            }
            dss[warp][lane] = dsv;
            stj[warp][lane] = j;
            stk[warp][lane] = k;
            __syncwarp();
            if (active) {
                for (uint32_t jj = part; jj < 32; jj += parts) {
                    const uint32_t jx = stj[warp][jj];
                    if (jx != UINT32_MAX) {
                        // [P54 step 4] `δs (D ŵ_j)`: the skin and the unit word on 32 bits (their product under `2^61`), then 64 by 64.
                        sum += mul64_128(dss[warp][jj], mul32((int64_t)skin_raw_at(w, h, m, g, srow + stk[warp][jj], jx > i ? jx - i : i - jx), words[(uint64_t)jx * S + entry]));
                    }
                }
            }
            __syncwarp();
        }
        // The crowds' δs, then their share of the row's return and of the values' and the word's member
        // returns through the difference arrays.
        if (cnts[warp][lane] != 0) {
            const wide dzc = compare((wide)w.ce[hg * w.slots + lane], dpcs[warp][lane]);
            const uint32_t clo = crlo[warp][lane], chi = crhi[warp][lane], clv = crlv[warp][lane];
            const int64_t cs = crowd_base_narrow(w, h, w.pq + ((uint64_t)h * w.T + g) * S, swp + (uint64_t)clo * S, swp + (uint64_t)(chi + 1) * S, cnts[warp][lane], clv, g, clo > i);
            tacc += rel(dzc * (wide)cs, FACE_BITS);
            const wide dz = rel(temper * dzc, MATERIAL_BITS);
            if ((dz < 0 ? -dz : dz) >> min(w.dsbits, 63u) != 0) {
                atomicOr(w.status, REFUSED_CARRIER);
            }
            dsks[warp][lane] = (int64_t)dz;
            if (w.cds != nullptr) {
                w.cds[hg * w.slots + lane] = (int64_t)dz;
            }
            far_ds += dz < 0 ? -dz : dz;
        }
        if (w.dsshare != nullptr) {
            near_ds = warp_sum(near_ds);
            far_ds = warp_sum(far_ds);
            if (lane == 0) {
                plain[(uint64_t)blockIdx.x * blockDim.x + threadIdx.x] = (near_ds);
                plain[(uint64_t)blockIdx.x * blockDim.x + threadIdx.x] = (far_ds);
            }
        }
        tacc = warp_sum(tacc);
        if (lane == 0 && tacc != 0) {
            // Into the temperature's own chart (§16.12): `δℓ = release(δT · release(T ln 2, 30), 24)`, the row's.
            plain[(uint64_t)blockIdx.x * blockDim.x + threadIdx.x] = (temper_chain(w, temper, tacc));
        }
        __syncwarp();
        if (active) {
            for (uint32_t jj = part; jj < nslots; jj += parts) {
                const uint64_t count = cnts[warp][jj];
                if (count == 0) {
                    continue;
                }
                const uint32_t lo = crlo[warp][jj], hi_ = crhi[warp][jj], lv = crlv[warp][jj];
                const wide d = crowd_skin_raw(w, h, m, g, lv, lo > i);
                const wide dsk = dsks[warp][jj];
                const wide wsum = swp[(uint64_t)(hi_ + 1) * S + entry] - swp[(uint64_t)lo * S + entry];
                // [P54 step 4] Where the crowd's summed word is under `2^31`: `D W`, `D ŵ_i` and `D²` on 32 bits (under `2^61`), their
                // products by the covector, the count and `W` as 64 by 64; otherwise the wide forms.
                int32_t w32;
                wide bracket;
                if (narrow31(wsum, &w32)) {
                    sum += div_nearest_by(mul64_128(dsks[warp][jj], mul32((int64_t)d, w32)), cdiv[warp][jj]);
                    // The key's bracket released by the skin's bits once, its product by the covector checked.
                    bracket = rel((mul64_128(mul32((int64_t)d, w.pq[((uint64_t)h * w.T + g) * S + entry]), (int64_t)count) << g0) - mul64_128(mul32((int64_t)d, (int64_t)d), w32), g0);
                } else {
                    RULER_LONG();
                    sum += div_nearest_by(dsk * d * wsum, cdiv[warp][jj]);
                    bracket = rel(((d * (wide)w.pq[((uint64_t)h * w.T + g) * S + entry] * (wide)count) << g0) - d * d * wsum, g0);
                }
                wide prod = 0;
                if (!mul_fits(dsk, bracket, &prod)) {
                    atomicOr(w.status, REFUSED_KEY);
                }
                const wide pw = div_nearest_by(prod, cdiv2[warp][jj]);
                plain[(uint64_t)blockIdx.x * blockDim.x + threadIdx.x] = (pw);
                plain[(uint64_t)blockIdx.x * blockDim.x + threadIdx.x] = (-pw);
                // [P54 step 4] The carried covector `release(D δỹ, 30)` on 64 bits (`carry_d`, under `2^63`), its share's product unsigned by signed.
                const int64_t cy = still ? dyi[entry] : carry_d((uint64_t)crowd_skin_ij(w, h, m, g, lv, lo > i), dyi[entry]);
                const wide pv = div_nearest_by(mulu64_128(w.ce[hg * w.slots + jj], cy), cdiv[warp][jj]);
                plain[(uint64_t)blockIdx.x * blockDim.x + threadIdx.x] = (pv);
                plain[(uint64_t)blockIdx.x * blockDim.x + threadIdx.x] = (-pv);
            }
        }
        sum = parts_sum(active ? sum : 0, S, parts);
        if (lane < S) {
            const uint32_t mc = h * n + lane % n;
            const uint64_t slot = g * w.M2 + (lane < n ? mc : w.M + mc);
            const int64_t probe_role = fit64(rel(sum, CONTACT_BACK + g0), w.status);
            // The probe role goes to the probe chart's covector, the key role (the columns) to the key's (§16.19).
            w.dp[slot] = probe_role;
            dq[slot] = 0;
        }
        __syncwarp();
    }
}

// field_contact_columns, mechanism n
extern "C" __global__ void __launch_bounds__(CONTACT_ROWS * 32) field_copy_n_contact_columns(FieldWords w, uint32_t h, const int64_t *dyh, const int64_t *ds, int64_t *dq, int64_t *dv) {
    const uint32_t lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const uint32_t parts = span_parts(S);
    const uint32_t entry = lane % S, part = lane / S, m = entry % n;
    const bool still = skinless(w, h);
    const uint32_t g0 = still ? 0 : MOVE_BITS;
    const bool paced_c = !still && paced_index(w, h) >= 0;
    for (uint64_t g = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; g < w.T; g += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint32_t r = w.site_region[g];
        const uint32_t j = w.site_pos[g];
        const uint64_t first = w.region_off[r];
        const uint32_t sites = w.region_off[r + 1] - (uint32_t)first;
        const uint32_t *members = w.members + (uint64_t)h * w.T + first;
        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t c = w.cls[(uint64_t)h * w.T + g];
        const uint32_t *poff = w.poff + ((uint64_t)h * w.R + r) * (classes + 1);
        const uint32_t *pmem = w.pmem + ((uint64_t)h * w.T + first) * probe_stride(w);
        const uint32_t *olist = w.olist + w.ostart[r];
        // A source with no key is in no receiver's support (§16.20).
        const uint32_t K = keyed_site(w, g) ? receiver_len(off, poff, w.ostart[r + 1] - w.ostart[r], c, definite_site(w, g)) : 0;
        const uint64_t *e = w.e + (uint64_t)h * w.E + w.region_eoff[r] + j;
        const int64_t *dsc = ds + w.region_eoff[r] + j;
        const int64_t *words = w.qf + ((uint64_t)h * w.T + first) * S;
        const int64_t *dyr = dyh + ((uint64_t)h * w.T + first) * S;
        wide sk = 0, sv = 0;
        if (part < parts) {
            for (uint32_t k = part; k < K; k += parts) {
                const uint32_t i = receiver_at(members, off, pmem, poff, olist, c, j, sites, k);
                if (i == UINT32_MAX || skipped_row(w, first + i)) {
                    continue;
                }
                const uint64_t at = (uint64_t)i * sites;
                const uint32_t gap = j > i ? j - i : i - j;
                // The pair's support entry in receiver `i`'s row (`support_entry`), where the clock's skins stand: read only on a paced head
                // whose pace is not plain there, the one row that reads the store.
                const uint64_t sentry = paced_c && paced_at(w, h, first + i) ? support_row(w, r, i) + support_entry(w, h, r, first, members, off, i, j) : 0;
                const wide dec = skin_raw_at(w, h, m, first + i, sentry, gap);
                // The key's bracket released by the skin's bits once (the probe's grain), then by the covector,
                // against the receiver's probe (§16.19).
                const int64_t probe_i = w.pq[((uint64_t)h * w.T + first + i) * S + entry];
                sk += (wide)dsc[at] * rel(((dec * (wide)probe_i) << g0) - dec * dec * (wide)words[(uint64_t)j * S + entry], g0);
                sv += (wide)e[at] * carried_ij_at(w, h, m, first + i, sentry, gap, dyr[(uint64_t)i * S + entry]);
            }
        }
        sk = parts_sum(part < parts ? sk : 0, S, parts);
        sv = parts_sum(part < parts ? sv : 0, S, parts);
        if (lane < S) {
            const uint32_t mc = h * n + lane % n;
            const uint64_t slot = g * w.M2 + (lane < n ? mc : w.M + mc);
            dq[slot] = fit64((wide)dq[slot] + rel(sk, CONTACT_BACK + g0), w.status);
            dv[slot] = fit64(rel(sv, SHARE_BITS), w.status);
        }
    }
}

// field_contact_columns, mechanism r
extern "C" __global__ void __launch_bounds__(CONTACT_ROWS * 32) field_copy_r_contact_columns(FieldWords w, uint32_t h, const int64_t *dyh, const int64_t *ds, int64_t *dq, int64_t *dv) {
    const uint32_t lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const uint32_t parts = span_parts(S);
    const uint32_t entry = lane % S, part = lane / S, m = entry % n;
    const bool still = skinless(w, h);
    const uint32_t g0 = still ? 0 : MOVE_BITS;
    const bool paced_c = !still && paced_index(w, h) >= 0;
    for (uint64_t g = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; g < w.T; g += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint32_t r = w.site_region[g];
