        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t c = w.cls[(uint64_t)h * w.T + g];
        const uint32_t *poff = w.poff + ((uint64_t)h * w.R + r) * (classes + 1);
        const uint32_t *pmem = w.pmem + ((uint64_t)h * w.T + first) * probe_stride(w);
        const uint32_t *olist = w.olist + w.ostart[r];
        // A source with no key is in no receiver's support (§16.20).
        const uint32_t K = keyed_site(w, g) ? receiver_len(off, poff, w.ostart[r + 1] - w.ostart[r], c, definite_site(w, g)) : 0;
        const uint64_t *e = w.e + (uint64_t)h * w.E + w.region_eoff[r] + j;
        const int64_t *dsc = ds + w.region_eoff[r] + j;
        const int64_t *words = w.qf + ((uint64_t)h * w.T + first) * S;
        const int64_t *dyr = dyh + ((uint64_t)h * w.T + first) * S;
        wide sk = 0, sv = 0;
        if (part < parts) {
            for (uint32_t k = part; k < K; k += parts) {
                const uint32_t i = receiver_at(members, off, pmem, poff, olist, c, j, sites, k);
                if (i == UINT32_MAX || skipped_row(w, first + i)) {
                    continue;
                }
                const uint64_t at = (uint64_t)i * sites;
                const uint32_t gap = j > i ? j - i : i - j;
                // The pair's support entry in receiver `i`'s row (`support_entry`), where the clock's skins stand: read only on a paced head
                // whose pace is not plain there, the one row that reads the store.
                const uint64_t sentry = paced_c && paced_at(w, h, first + i) ? support_row(w, r, i) + support_entry(w, h, r, first, members, off, i, j) : 0;
                const wide dec = skin_raw_at(w, h, m, first + i, sentry, gap);
                // The key's bracket released by the skin's bits once (the probe's grain), then by the covector,
                // against the receiver's probe (§16.19).
                const int64_t probe_i = w.pq[((uint64_t)h * w.T + first + j) * S + entry];
                sk += (wide)dsc[at] * rel(((dec * (wide)probe_i) << g0) - dec * dec * (wide)words[(uint64_t)j * S + entry], g0);
                sv += (wide)e[at] * carried_ij_at(w, h, m, first + i, sentry, gap, dyr[(uint64_t)j * S + entry]);
            }
        }
        sk = parts_sum(part < parts ? sk : 0, S, parts);
        sv = parts_sum(part < parts ? sv : 0, S, parts);
        if (lane < S) {
            const uint32_t mc = h * n + lane % n;
            const uint64_t slot = g * w.M2 + (lane < n ? mc : w.M + mc);
            dq[slot] = fit64((wide)dq[slot] + rel(sk, CONTACT_BACK + g0), w.status);
            dv[slot] = fit64(rel(sv, SHARE_BITS), w.status);
        }
    }
}

// field_contact_columns, mechanism c: each source's count of receivers
extern "C" __global__ void __launch_bounds__(CONTACT_ROWS * 32) field_copy_c_columns_count(FieldWords w, uint32_t h, const int64_t *dyh, const int64_t *ds, int64_t *dq, int64_t *dv, uint32_t *kout) {
    const uint32_t lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const uint32_t parts = span_parts(S);
    const uint32_t entry = lane % S, part = lane / S, m = entry % n;
    const bool still = skinless(w, h);
    const uint32_t g0 = still ? 0 : MOVE_BITS;
    const bool paced_c = !still && paced_index(w, h) >= 0;
    for (uint64_t g = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; g < w.T; g += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint32_t r = w.site_region[g];
        const uint32_t j = w.site_pos[g];
        const uint64_t first = w.region_off[r];
        const uint32_t sites = w.region_off[r + 1] - (uint32_t)first;
        const uint32_t *members = w.members + (uint64_t)h * w.T + first;
        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t c = w.cls[(uint64_t)h * w.T + g];
        const uint32_t *poff = w.poff + ((uint64_t)h * w.R + r) * (classes + 1);
        const uint32_t *pmem = w.pmem + ((uint64_t)h * w.T + first) * probe_stride(w);
        const uint32_t *olist = w.olist + w.ostart[r];
        // A source with no key is in no receiver's support (§16.20).
        const uint32_t K = keyed_site(w, g) ? receiver_len(off, poff, w.ostart[r + 1] - w.ostart[r], c, definite_site(w, g)) : 0;
        if (lane == 0) {
            kout[g] = K;
        }
    }
}

// field_contact_columns, mechanism c: the record in column order
extern "C" __global__ void __launch_bounds__(CONTACT_ROWS * 32) field_copy_c_columns_record(FieldWords w, uint32_t h, const int64_t *dyh, const int64_t *ds, int64_t *dq, int64_t *dv, const uint64_t *rec_off, uint32_t *rec_i, int64_t *rec_ds, uint64_t *rec_e, uint32_t *rec_dec) {
    const uint32_t lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const uint32_t parts = span_parts(S);
    const uint32_t entry = lane % S, part = lane / S, m = entry % n;
    const bool still = skinless(w, h);
    const uint32_t g0 = still ? 0 : MOVE_BITS;
    const bool paced_c = !still && paced_index(w, h) >= 0;
    for (uint64_t g = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; g < w.T; g += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint32_t r = w.site_region[g];
        const uint32_t j = w.site_pos[g];
        const uint64_t first = w.region_off[r];
        const uint32_t sites = w.region_off[r + 1] - (uint32_t)first;
        const uint32_t *members = w.members + (uint64_t)h * w.T + first;
        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t c = w.cls[(uint64_t)h * w.T + g];
        const uint32_t *poff = w.poff + ((uint64_t)h * w.R + r) * (classes + 1);
        const uint32_t *pmem = w.pmem + ((uint64_t)h * w.T + first) * probe_stride(w);
        const uint32_t *olist = w.olist + w.ostart[r];
        // A source with no key is in no receiver's support (§16.20).
        const uint32_t K = keyed_site(w, g) ? receiver_len(off, poff, w.ostart[r + 1] - w.ostart[r], c, definite_site(w, g)) : 0;
        const uint64_t *e = w.e + (uint64_t)h * w.E + w.region_eoff[r] + j;
        const int64_t *dsc = ds + w.region_eoff[r] + j;
        const int64_t *words = w.qf + ((uint64_t)h * w.T + first) * S;
        const int64_t *dyr = dyh + ((uint64_t)h * w.T + first) * S;
        // The source's record from its offset (P59 (c)): its receivers in column order, `K` of them (a receiver heard twice stands twice).
        const uint64_t rbase = rec_off[g];
        wide sk = 0, sv = 0;
        {
            for (uint32_t k = lane; k < K; k += 32) {
                const uint32_t i = receiver_at(members, off, pmem, poff, olist, c, j, sites, k);
                const uint64_t rk = rbase + k;
                if (i == UINT32_MAX || skipped_row(w, first + i)) {
                    rec_i[rk] = UINT32_MAX;
                    continue;
                }
                const uint64_t at = (uint64_t)i * sites;
                const uint32_t gap = j > i ? j - i : i - j;
                const uint64_t sentry = paced_c && paced_at(w, h, first + i) ? support_row(w, r, i) + support_entry(w, h, r, first, members, off, i, j) : 0;
                rec_i[rk] = i;
                rec_ds[rk] = dsc[at];
                rec_e[rk] = e[at];
                for (uint32_t l = 0; l < n; l++) {
                    rec_dec[rk * n + l] = (uint32_t)skin_raw_at(w, h, l, first + i, sentry, gap);
                }
            }
        }
    }
}

// field_contact_columns, mechanism c
extern "C" __global__ void __launch_bounds__(CONTACT_ROWS * 32) field_copy_c_contact_columns(FieldWords w, uint32_t h, const int64_t *dyh, const int64_t *ds, int64_t *dq, int64_t *dv, const uint64_t *rec_off, const uint32_t *rec_i, const int64_t *rec_ds, const uint64_t *rec_e, const uint32_t *rec_dec) {
    const uint32_t lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const uint32_t parts = span_parts(S);
    const uint32_t entry = lane % S, part = lane / S, m = entry % n;
    const bool still = skinless(w, h);
    const uint32_t g0 = still ? 0 : MOVE_BITS;
    const bool paced_c = !still && paced_index(w, h) >= 0;
    for (uint64_t g = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; g < w.T; g += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint32_t r = w.site_region[g];
        const uint32_t j = w.site_pos[g];
        const uint64_t first = w.region_off[r];
        const uint32_t sites = w.region_off[r + 1] - (uint32_t)first;
        const uint32_t *members = w.members + (uint64_t)h * w.T + first;
        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t c = w.cls[(uint64_t)h * w.T + g];
        const uint32_t *poff = w.poff + ((uint64_t)h * w.R + r) * (classes + 1);
        const uint32_t *pmem = w.pmem + ((uint64_t)h * w.T + first) * probe_stride(w);
        const uint32_t *olist = w.olist + w.ostart[r];
        // A source with no key is in no receiver's support (§16.20).
        const uint32_t K = keyed_site(w, g) ? receiver_len(off, poff, w.ostart[r + 1] - w.ostart[r], c, definite_site(w, g)) : 0;
        const uint64_t *e = w.e + (uint64_t)h * w.E + w.region_eoff[r] + j;
        const int64_t *dsc = ds + w.region_eoff[r] + j;
        const int64_t *words = w.qf + ((uint64_t)h * w.T + first) * S;
        const int64_t *dyr = dyh + ((uint64_t)h * w.T + first) * S;
        // The source's record from its offset (P59 (c)): its receivers in column order, `K` of them (a receiver heard twice stands twice).
        const uint64_t rbase = rec_off[g];
        wide sk = 0, sv = 0;
        if (part < parts) {
            for (uint32_t k = part; k < K; k += parts) {
                const uint64_t rk = rbase + k;
                const uint32_t i = rec_i[rk];
                if (i == UINT32_MAX) {
                    continue;
                }
                const wide dec = (wide)rec_dec[rk * n + m];
                const int64_t probe_i = w.pq[((uint64_t)h * w.T + first + i) * S + entry];
                sk += (wide)rec_ds[rk] * rel(((dec * (wide)probe_i) << g0) - dec * dec * (wide)words[(uint64_t)j * S + entry], g0);
                const int64_t vy = dyr[(uint64_t)i * S + entry];
                sv += (wide)rec_e[rk] * (still ? (wide)vy : rel(dec * (wide)vy, MOVE_BITS));
            }
        }
        sk = parts_sum(part < parts ? sk : 0, S, parts);
        sv = parts_sum(part < parts ? sv : 0, S, parts);
        if (lane < S) {
            const uint32_t mc = h * n + lane % n;
            const uint64_t slot = g * w.M2 + (lane < n ? mc : w.M + mc);
            dq[slot] = fit64((wide)dq[slot] + rel(sk, CONTACT_BACK + g0), w.status);
            dv[slot] = fit64(rel(sv, SHARE_BITS), w.status);
        }
    }
}

// field_pace_skin_back, mechanism n
extern "C" __global__ void __launch_bounds__(CONTACT_ROWS * 32) field_copy_n_pace_skin_back(FieldWords w, uint32_t h, const int64_t *dyh, const int64_t *ds) {
    __shared__ RowCls rcs[CONTACT_ROWS];
    // [theory, November 13, P55 step 5] Each mode's turn rate `b_l = release(2π/n_l, 16)` read once a block (`turn_rate_dev`): the quotient is the
    // head's and the mode's, the same at every pair and crowd of every row (at most 16 modes: the card's span is at most 32 entries).
    __shared__ wide turn_b[16];
    const uint32_t warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
    const uint32_t S = w.span, n = w.n, classes = w.nclasses;
    const int32_t p = paced_index(w, h);
    if (p < 0) {
        return;
    }
    for (uint32_t l = threadIdx.x; l < n; l += blockDim.x) {
        turn_b[l] = turn_rate_dev(w, l * (w.frames - w.still) + h % w.frames - w.still);
    }
    __syncthreads();
    const uint64_t rows1 = (uint64_t)w.T + w.R;
    for (uint64_t g = ((uint64_t)blockIdx.x * blockDim.x + threadIdx.x) >> 5; g < w.T; g += (uint64_t)gridDim.x * (blockDim.x >> 5)) {
        const uint64_t hg = (uint64_t)h * w.T + g;
        // [E] A row the cut room did not compute met no source: its skins return nothing.
        if (skipped_row(w, g)) {
            continue;
        }
        const uint32_t r = w.site_region[g];
        const uint64_t first = w.region_off[r];
        const uint32_t sites = w.region_off[r + 1] - (uint32_t)first, i = w.site_pos[g];
        const uint32_t *members = w.members + (uint64_t)h * w.T + first;
        const uint32_t *off = w.class_off + ((uint64_t)h * w.R + r) * (2 * classes + 1);
        const uint32_t K = row_prepare(w, hg, off, rcs[warp], lane);
        const uint64_t *e = w.e + (uint64_t)h * w.E + w.region_eoff[r] + (uint64_t)i * sites;
        const int64_t *dsr = ds + w.region_eoff[r] + (uint64_t)i * sites;
        const int64_t *dyi = dyh + hg * S;
        const int64_t *values = w.vf + ((uint64_t)h * w.T + first) * S;
        const int64_t *words = w.qf + ((uint64_t)h * w.T + first) * S;
        const int64_t *wi = w.pq + hg * S;
        const int64_t *sigma = w.sigma + (uint64_t)p * w.T;
        // The row's support entries' addresses (the clock's skins stand there).
        const uint64_t srow = support_row(w, r, i);
        const uint64_t prow0 = (uint64_t)h * rows1 + first + r;
        const wide *swp = w.sw + prow0 * S;
        const wide *svp = w.sv + prow0 * S;
        const uint64_t *scp = w.sc + prow0;
        const uint32_t nslots = rcs[warp].open ? 0 : crowd_slots(sites);
        wide own = 0;
        for (uint32_t k = lane; k < K; k += 32) {
            const uint32_t j = support_at(members, off, rcs[warp], i, sites, k);
            if (j == UINT32_MAX) {
                continue;
            }
            const uint64_t gj = first + j;
            const wide sgn = sigma[g] > sigma[gj] ? 1 : sigma[g] < sigma[gj] ? -1 : 0;
            if (sgn == 0) {
                continue;
            }
            const uint32_t gap = j > i ? j - i : i - j;
            wide at = 0;
            // [P55 step 5] The modes' sums to the source's covector, added on the lane and summed once (a ring sum on `Z/2^128`: the same bits).
            uwide to_source = 0;
            for (uint32_t l = 0; l < n; l++) {
                const wide dec = skin_ij_at(w, h, l, g, srow + k, gap);
                // [P54 step 4] `Re(conj(δỹ) ṽ)` as two 64 by 64 products (each under `2^126`, their sum under `2^127`).
                const wide inner = mul64_128(dyi[l], values[(uint64_t)j * S + l]) + mul64_128(dyi[n + l], values[(uint64_t)j * S + n + l]);
                wide value = 0;
                if (!mul_fits((wide)e[j], inner, &value)) {
                    atomicOr(w.status, REFUSED_CARRIER);
                }
                value = rel(value, SHARE_BITS);
                // [P54 step 4] The lock's pairing `w·k` and power `|k|²` from 32-bit products (unit words), `2 D |k|²` as 64 by 64 unsigned.
                const int64_t kr = words[(uint64_t)j * S + l], ki = words[(uint64_t)j * S + n + l];
                const wide pairing = (wide)mul32(wi[l], kr) + (wide)mul32(wi[n + l], ki);
                const uint64_t power = (uint64_t)mul32(kr, kr) + (uint64_t)mul32(ki, ki);
                const wide bracket = (pairing << (MOVE_BITS + 1)) - (wide)mulu64(power, 2 * (uint64_t)dec);
                wide lock = 0;
                if (!mul_fits((wide)dsr[j], bracket, &lock)) {
                    atomicOr(w.status, REFUSED_KEY);
                }
                lock = rel(lock, 2 * FACE_BITS + 1 + 2 * MOVE_BITS - MOVE_BITS);
                at = skin_back_proved(turn_b[l], dec, value + lock);
                own -= sgn * at;
                to_source += (uwide)(sgn * at);
            }
            add_wide(w.gsig + (uint64_t)p * w.T + gj, (wide)to_source);
        }
        if (lane < nslots) {
            uint32_t lo, hi_, lv;
            if (crowd_at(i, sites, lane, &lo, &hi_, &lv)) {
                const uint64_t count = scp[hi_ + 1] - scp[lo];
                const bool right = lo > i;
                const uint64_t ge = octave_edge(g, lv, right);
                const wide sgn = sigma[g] > sigma[ge] ? 1 : sigma[g] < sigma[ge] ? -1 : 0;
                if (count != 0 && sgn != 0) {
                    const wide cnt = (wide)count;
                    // [P55 step 5] The quotients by the count and its square (a mode's value and bracket) by divisors read once a crowd
                    // (`div_nearest_by`, the same integer: `⌊(|x| + ⌊k/2⌋)/k⌋` either way; `count < 2^32`, so `count² < 2^64`), and the modes' sums to
                    // the edge's covector added on the lane and summed once.
                    const Divisor qc = divisor_of(count), qc2 = divisor_of(count * count);
                    uwide to_edge = 0;
                    for (uint32_t l = 0; l < n; l++) {
                        const wide dec = crowd_skin_ij(w, h, l, g, lv, right);
                        const wide vr = svp[(uint64_t)(hi_ + 1) * S + l] - svp[(uint64_t)lo * S + l], vi = svp[(uint64_t)(hi_ + 1) * S + n + l] - svp[(uint64_t)lo * S + n + l];
                        wide x = 0, y = 0, value = 0;
                        if (!mul_fits((wide)dyi[l], vr, &x) || !mul_fits((wide)dyi[n + l], vi, &y) || !mul_fits((wide)w.ce[hg * w.slots + lane], x + y, &value)) {
                            atomicOr(w.status, REFUSED_CARRIER);
                        }
                        value = div_nearest_by(rel(value, SHARE_BITS), qc);
                        const wide wr = wi[l], wim = wi[n + l];
                        const wide mr = swp[(uint64_t)(hi_ + 1) * S + l] - swp[(uint64_t)lo * S + l], mi = swp[(uint64_t)(hi_ + 1) * S + n + l] - swp[(uint64_t)lo * S + n + l];
                        // [P54 step 4] Where the crowd's summed words are under `2^31`: its pairing and power from 32-bit products (sums under
                        // `2^63`), their products by `2|C|` and `2D` as 64 by 64; otherwise the wide forms.
                        int32_t mr32, mi32;
                        wide bracket;
                        if (narrow31(mr, &mr32) & narrow31(mi, &mi32)) {
                            const int64_t pairing = mul32(wi[l], mr32) + mul32(wi[n + l], mi32);
                            const int64_t power = mul32(mr32, mr32) + mul32(mi32, mi32);
                            bracket = div_nearest_by((mul64_128(pairing, 2 * (int64_t)count) << MOVE_BITS) - mul64_128(power, 2 * (int64_t)dec), qc2);
                        } else {
                            RULER_LONG();
                            bracket = div_nearest_by(((2 * cnt * (wr * mr + wim * mi)) << MOVE_BITS) - 2 * dec * (mr * mr + mi * mi), qc2);
                        }
                        wide lock = 0;
                        if (!mul_fits((wide)w.cds[hg * w.slots + lane], bracket, &lock)) {
                            atomicOr(w.status, REFUSED_KEY);
                        }
                        lock = rel(lock, 2 * FACE_BITS + 1 + MOVE_BITS);
                        const wide at = skin_back_proved(turn_b[l], dec, value + lock);
                        own -= sgn * at;
                        to_edge += (uwide)(sgn * at);
                    }
                    add_wide(w.gsig + (uint64_t)p * w.T + ge, (wide)to_edge);
                }
            }
        }
        own = warp_sum(own);
        if (lane == 0 && own != 0) {
            add_wide(w.gsig + (uint64_t)p * w.T + g, own);
        }
    }
}

